programs.sol:
"""Lexical cues for introducing assumptions, examples, and named quantities.

Predict negative activations on setup verbs, especially imperatives and
'let me/us/\'s ...'. Give 'be' a strong response after a recent 'let',
weakening with the gap, but not after modal auxiliaries. Case and spacing
help distinguish prose 'let' from code and word fragments. Some responses
extend to the following subject or article. Other tokens stay near zero.
These are approximate cues, not a sentence parser; history resets per document.
"""
import math

READS = ()
# Ordinary, imperative, 'let me/us/\'s', and 'we' uses of setup verbs.
VERBS = {
    'suppose': (-1.3, -2.9, -4.0, -2.5),
    'assume': (-0.7, -1.8, -2.9, -1.6),
    'consider': (-0.2, -1.5, -2.5, -1.1),
    'denote': (-1.4, -2.0, -2.8, -1.5),
    'say': (-0.35, -1.5, -3.6, -1.2),
    'take': (-0.12, -0.8, -1.6, -0.5),
    'imagine': (-0.7, -2.1, -2.2, -0.7),
    'define': (-0.15, -0.5, -1.1, -0.55),
    'think': (0.04, -0.4, -0.95, -0.15),
    'see': (0.06, 0.0, -0.5, 0.0),
}
MODALS = set('can could shall should will would may might must cannot'.split())
COMPLEMENTS = {'me', 'us', "'s", '’s'}
DERIVED = {'assuming', 'supposed', 'assumed', 'considering'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    previous = history[-1] if history else ''
    recent = [s.strip().lower() for s in history]
    prev = recent[-1] if recent else ''
    joined = prev.lstrip('./') + word
    split = not raw[:1].isspace() and (joined in VERBS or joined in DERIVED)
    if split:
        word = joined
    invitation = 'let' in recent[-4:] and prev in COMPLEMENTS
    command = token.istitle() or prev in {',', ':', 'now'}
    value = -0.001

    if word == 'let':
        value = -0.08
        if token == 'Let':
            value = -1.8 if '\n' in previous else -1.45
            if 'assistant' in recent[-4:]:
                value = -0.8
            if not history:
                value = -3.7
        elif raw == ' let':
            if prev in {',', 'so', 'now', 'wait', 'first', 'then'} | COMPLEMENTS:
                value = -1.15
            elif previous.rstrip().endswith((')', '$')):
                value = -1.5
            elif prev in {'and', 'but', ':'}:
                value = -0.7
    elif word in VERBS and (split or not token.isupper()):
        ordinary, imperative, invitation_value, after_we = VERBS[word]
        value = (invitation_value if invitation else after_we if prev == 'we'
                 else imperative if command or split else ordinary)
        if split and word in {'suppose', 'assume', 'imagine'}:
            value = {'suppose': -4.0, 'assume': -2.8, 'imagine': -0.7}[word]
        if word == 'consider' and (split or raw == 'Consider'):
            value = -2.2
        if word == 'consider' and 'example' in recent[-3:]:
            value = -2.7
        if word == 'suppose' and prev in {'and', 'so', 'now', 'but'}:
            value = -2.6
        if word == 'say':
            if prev == ',':
                value = -1.75
            elif prev == 'let':
                value = -4.0
    elif token == 'Sup':
        value = -1.5 if raw == 'Sup' and '\n' in previous else -0.5
    elif raw == 'Ass':
        value = -0.9
    elif word == 'be':
        value = -0.2 if token == 'be' else -0.1
        if prev in MODALS | {'to', 'not', "'t", '’t', 'also'}:
            value = 0.01
        elif 'let' in recent:
            start = max(i for i, w in enumerate(recent) if w == 'let')
            distance = len(recent) - start
            value = (-3.5 if distance <= 4 else
                     -0.8 - 2.0 * math.exp(-0.18 * (distance - 5)))
            if any(w in COMPLEMENTS for w in recent[start + 1:]) and distance > 8:
                value = -0.2
        elif not history:
            value = -0.87
        elif raw == ' be' and prev and not prev[-1].isalnum():
            value = -0.6
    elif word == 'given':
        value = -0.65 if token.istitle() else -0.16
    elif word in DERIVED | {'pretend'}:
        value = -0.8 if split else -0.4
    # The response can extend to the first subject or article of the setup.
    prev_word = carry[2] if history else ''
    prev_value = carry[3] if history else 0.0
    if (token.islower() or token == 'I') and raw[:1].isspace():
        if prev_word in {'suppose', 'say'} and word in {'we', 'you', 'i', 'a', 'two'}:
            value = 0.45 * prev_value
        elif prev_word in {'consider', 'given'} and word in {'a', 'an', 'the', 'two'}:
            value = (0.6 if word in {'a', 'an'} else 0.25) * prev_value
        elif word == 'have' and prev in {'i', 'we', 'you'}:
            value = -0.3
        elif word == 'a' and prev in {'have', 'has'}:
            value = -0.25
        elif word == 'of' and prev == 'think':
            value = -0.55
    return (doc, (history + (raw,))[-24:], word, value), float(value)

"""A mostly lexical detector for unit/units, not measurement in general.

The literal spellings and Chinese unit words get large responses. Related
un-/uni- strings, translated unit words, 'single', and unsplit software
unit-test names get smaller responses. Numbers and word-internal spellings
adjust the level. The previous token identifies split words and phrases
such as 'unit(s) of', 'university of', and 'United States'. Other tokens
return zero: weak, idiosyncratic lexical responses are deliberately omitted.
"""
READS = ()


def word(text):
    return text.strip().lstrip("._/\\(-").lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry and carry[0] == doc else ""
    text = prefix.token_strings[-1]
    w, p = word(text), word(prev)
    bare = text.strip().lstrip("._/\\(-")
    number = prev.strip().isdigit()

    if w == "unit":
        value = 6.9
        if number:
            value = 6.0
        if text == "Unit":
            value = 7.2
        elif text == "unit" and prev[-1:].isalpha():
            value = 5.0
            if p == "php":
                value = 9.9
            elif p == "sub":
                value = 8.1
            elif p == "j":
                value = 4.3 if prev == "j" else 6.3
        elif text.startswith((".U", "(U")):
            value = 5.0
        elif text.startswith("\\U"):
            value = 4.2
    elif w == "units":
        value = 5.4 if number else 6.2
    elif w in {"单位", "單位"}:
        value = 6.4 if w == "单位" else 5.5
    elif w in {"单元", "單元"}:
        value = 2.7
    elif w in {"unidad", "unidades"}:
        value = 3.2 if text.startswith(" ") else 1.8
    elif w == "unità":
        value = 2.0
    elif w == "single":
        value = 0.23
    elif w.endswith("unit") and w[:-4].isalpha():
        value = 0.8 if w in {"junit", "phpunit"} else 2.5
    elif w == "unittest":
        value = 2.0
    elif w in {"单", "單", "単"}:
        value = 0.9
    elif w in {"元", "位"}:
        value = 0.5
    elif w == "of" and p in {"unit", "units", "university"}:
        if p == "university":
            value = 0.45
        elif p == "units":
            value = 2.5
        else:
            value = 2.8 if prev.startswith(" ") else 1.3
    elif w == "united":
        value = 1.4 if bare != "united" else 1.06
    elif w in {"university", "universität"}:
        value = 1.3
    elif w == "universities":
        value = 0.9
    elif w in {"大学", "大學", "学校", "學校", "高校"}:
        value = 0.55
    elif w == "until":
        value = 0.95 if bare == "until" else 1.4
    elif w == "直到":
        value = 0.75
    elif w in {"states", "kingdom"} and p == "united":
        value = 0.87 if w == "states" else 0.56
        if prev.strip() == "united":
            value = 0.32 if w == "states" else 0.04
    elif p == "un" and w in {"its", "ions", "ittest", "ited"}:
        value = {"its": 5.3, "ions": 1.0, "ittest": 1.7, "ited": 1.4}[w]
    elif w == "un":
        value = 0.2 if bare == "un" else 0.7
        if text.startswith("/"):
            value = 1.7
        elif text.startswith("-") and bare == "un":
            value = 2.4
        elif text.startswith("("):
            value = 1.1
    elif w == "ユニ":
        value = 1.9
    elif w in {"uni", "universe", "unity", "uns"}:
        value = 0.6
    elif w.startswith("uint") or w in {"util", "utils"}:
        value = 0.9
    else:
        value = 0.0
    return (doc, text), float(value)

programs.haiku:
"""Layer-0 MLP component 3266 (down_proj): a detector for the word "unit".

It writes a large value into the residual stream on the token "unit" / "units" (any case,
with or without a leading space or punctuation, and Chinese 单位), and a weaker value on
words that share its "un-"/"uni-" look: United, University, until, unity, util(s).
Two context rules: the " States" after "United" (United States), and " of" right after a
unit word ("a unit of pressure").  Everything else is 0.

Whole words only: "community", "opportunity" and "immunity" do not fire.
"""

READS = ()

UNIT_WORD = {"unit": 7.0, "units": 6.0, "单位": 6.5}
UN_WORDS = {"united", "university", "until", "unity", "unite", "unto", "util", "utils",
            "utility", "utilities", "universities", "universe"}


def _word(token):
    # the token decoded alone, with its leading space, separators and case removed
    return token.strip().lower().strip("_-./(")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = _word(prefix.token_strings[-2]) if same_doc else ""
    if word in UNIT_WORD:
        return carry, UNIT_WORD[word]
    if before in UNIT_WORD and token == " of":
        return carry, 2.9
    if word in UN_WORDS:
        return carry, 1.2
    if before == "united" and word == "states":
        return carry, 0.9
    return carry, 0.0

programs.luna:
"""Estimate a sparse lexical feature for ``un...`` words.

This component is mostly quiet. It rises most on the literal ``unit``
spelling, and modestly on other tokens beginning ``un``. It also responds
to a few continuations of split words (notably ``United States``).
"""
READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    previous, previous_doc = carry or ("", None)
    if previous_doc != doc:
        previous = ""

    if text == "united":
        value = 1.35
    elif text.startswith("unit"):
        value = 5.8
    elif text.startswith("univ"):
        value = 1.5
    elif text.startswith("un"):
        value = 0.6
    elif previous == "united" and text in {"states", "kingdom"}:
        value = 0.85 if text == "states" else 0.55
    elif previous == "un" and text == "ions":
        value = 1.0
    else:
        value = 0.0

    return (text, doc), value

programs.haiku:
"""Surface and face detector for one MLP output direction (layer 0, down_proj unit 3267).

What it does: the component reads the current token and writes a signed amount that
depends on what that token means.
- Words for a surface or face are strongly negative: "surface" (about -5.5), the Chinese
  character 面 (face, surface or side, in compounds such as 表面, 地面, 一面, about -4.5),
  "face" (about -3.2), and "interface" (about -2.2).
- Flat-surface and edge nouns are weakly negative (about -0.8): side, front, screen,
  plane, ground, floor, wall.
- The end-of-text token <|endoftext|> is positive (about +1.7).
- Every other token gives 0.

The program is stateless: it reads only the newest token, so document boundaries
do not matter. Its values are rounded group means measured on training text.
"""

END_OF_TEXT = "<|endoftext|>"
SURFACE = {"surface", "surfaces", "surf", "urface"}
INTERFACE = {"interface", "interfaces"}
FACE = {"face", "faces", "faced", "facing", "-face", "confront"}
FLAT = {"side", "sides", "front", "screen", "plane", "ground", "floor", "wall"}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if token == END_OF_TEXT:
        value = 1.7
    elif "面" in token:
        value = -4.5
    elif word in SURFACE:
        value = -5.5
    elif word in INTERFACE:
        value = -2.2
    elif word in FACE:
        value = -3.2
    elif word in FLAT:
        value = -0.8
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate a sparse detector for technical entities and quantities.

The component tends to activate on nouns naming scientific ingredients,
materials, organisms, and abstract parts or variables. This compact lexical
rule misses many context-dependent cases and is not a semantic classifier.
"""
READS = ()

MATERIALS = frozenset({
    "chemical", "chemicals", "drug", "drugs", "fluid", "fluids",
    "ingredient", "ingredients", "material", "materials", "fuel",
    "fuels", "salt", "salts", "food", "foods", "toxic",
    "particle", "particles", "solution", "solutions",
    "substance", "substances", "matter", "compound", "compounds",
})
LIFE = frozenset({
    "gene", "genes", "genome", "genomes", "bacterium", "bacteria",
    "species", "organism", "organisms", "cell", "cells",
    "protein", "proteins", "molecule", "molecules", "tissue", "tissues",
})
CONCRETE = frozenset({
    "planet", "planets", "weapon", "weapons", "drink", "drinks",
})
ABSTRACT = frozenset({
    "factor", "factors", "component", "components", "variable",
    "variables", "element", "elements", "parameter", "parameters",
    "object", "objects", "entity", "entities", "property", "properties",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().strip(".,:;!?()[]{}\"'“”‘’")
    word = token.casefold()
    if word in {"药", "材料", "神", "種"}:
        return None, -0.8
    if word in MATERIALS:
        return None, -1.0
    if word in LIFE:
        return None, -0.9
    if word in ABSTRACT:
        return None, -0.7
    if word in CONCRETE:
        return None, -0.55
    return None, 0.0

programs.sol:
"""A mostly lexical detector of completed actions and changed states.

Chinese 了 is by far the strongest cue: alone or attached to a verb it
receives a large positive value. Its non-perfective uses and tokens that
continue past it receive smaller values. Other Chinese aspect/result
words and Japanese, Korean, Vietnamese and Thai past/completion markers
receive weaker positives, as do selected English and Russian past forms.
Values are rounded summaries of training activations for these groups.
Unrecognized text receives zero; most contextual variation is omitted.
"""
READS = ()

# Done/formed/appeared/produced/came to have, with perfective 了.
EVENT_LE = {'进行了', '形成了', '出现了', '产生了', '有了'}
SUFFICIENCY = {'就好了', '就可以了', '就行了', '可以了', '够了', '就够了'}
EXISTENTIAL = {'只有', '还有', '還有', '有一', '有一些', '有多', '有什么',
               '有什麼', '拥有', '擁有', '会有', '有哪些', '有很多', '有许多'}
COPULAS = {'就是', '也是', '都是', '的是', '是一', '是一种', '是一種',
           '正是', '以下是', '的就是'}
# Result and direction complements: out, up, stay, down, come, go, drop.
RESULTS = {'出', '起', '住', '下', '来', '來', '去', '掉', '出来', '出來', '一下'}
COMPLETION = {'完', '完成', '实现', '實現', '出现', '出現', '形成', '成为', '成為'}
ENGLISH_PAST = {'got', 'came', 'became', 'gave', 'wrote', 'occurred', 'threw'}
JAPANESE_STATE = {'では', 'のです', 'しています', 'っている', 'れている',
                  'ている', 'となります', 'になります', 'となっています'}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    previous = prefix.token_strings[-2] if prefix.position else ''
    same_document = (prefix.position and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    if not same_document:
        previous = ''
    value = 0.0
    if '了' in s:
        if '了解' in s:
            value = 0.7
        elif s == '了':
            # In Japanese 終了/修了, this is part of a word for finishing.
            value = 2.7 if previous.endswith(('終', '修')) else 5.5
        elif s.endswith(('为了', '為了', '罢了', '罷了')):
            value = 3.3
        elif s.endswith('除了'):
            value = 3.6
        elif s.endswith('不了') or s in SUFFICIENCY:
            value = 2.9
        elif s in EVENT_LE:
            value = 6.5
        elif s == '到了':
            value = 5.2
        elif s.endswith('了'):
            value = 5.9
        elif s == '了一':
            value = 4.3
        elif s in {'了吧', '了吗', '了嗎', '了个', '了個', '了一下'}:
            value = 2.6
        elif s.startswith('了'):
            value = 3.5
        else:
            value = 2.4
        if not same_document and s == '了':
            value = 3.5
    elif s == '啦':
        value = 2.1
    elif s.endswith('着'):
        value = 1.1
    elif s in {'著', '过', '過'}:
        value = 0.65
    elif s == '错过':
        value = 1.65
    elif s == '到':
        value = 0.6
    elif s.endswith(('到', '看过', '说过', '看過', '說過')):
        value = 0.8
    elif s in {'缺乏', '缺少'}:
        value = 1.0
    elif s in {'没', '沒'}:
        value = 0.6
    elif '没有' in s or '沒有' in s or s.endswith(('没', '沒')):
        value = 0.95
    elif s in EXISTENTIAL:
        value = 0.8
    elif s in COPULAS:
        value = 0.7
    elif s in {'是', '有'}:
        value = 0.17
    elif s in RESULTS:
        value = 0.4
    elif s.endswith(('出', '住')) and all('\u4e00' <= c <= '\u9fff' for c in s):
        value = 0.6
    elif s in {'做好', '准备好', '準備好', '带来', '帶來'}:
        value = 0.8
    elif s in COMPLETION:
        value = 0.55
    # Japanese -shimatta/-shimaimashita explicitly marks completion.
    elif s.endswith(('しまった', 'しまいました')):
        value = 2.3
    elif s.endswith('ました'):
        value = 1.3
    elif s.endswith('った'):
        value = 0.85
    elif s == 'でした':
        value = 0.9
    elif s in {'した', 'た'}:
        value = 0.4
    elif s.endswith('した'):
        value = 0.8
    elif s in JAPANESE_STATE:
        value = 0.65
    elif s.endswith(('했다', '었다', '았다', '였다', '하였', '았', '었')):
        value = 1.3
    elif s in {'렸', '겼', '했', '였', '됐'}:
        value = 1.0
    # Vietnamese 'already'; Thai 'already' and its tokenizer fragments.
    elif s in {'rồi', 'แล้ว', 'แล', '้ว'}:
        value = 1.3
    elif s in {'был', 'была', 'было', 'были', 'стал', 'стала', 'стало', 'стали'}:
        value = 0.5
    elif s.lower() in ENGLISH_PAST:
        value = 0.3
    return None, float(value)

programs.luna:
"""Read the first word after a relative clause marker as a rough grammar cue.

After “that” or “which”, subjects, auxiliary verbs, and articles tend to have
negative activations. Other following words are given a small positive estimate.
"""

READS: tuple[str, ...] = ()

PRONOUNS = {"i", "me", "we", "us", "you", "he", "she", "it", "they",
            "him", "her", "them"}
BE_VERBS = {"am", "is", "are", "was", "were", "be", "been", "being"}
MODALS = {"can", "could", "may", "might", "must", "shall", "should",
          "will", "would"}
ARTICLES = {"a", "an", "the"}
AUXILIARIES = {"have", "has", "had", "do", "does", "did"}


def step(carry, prefix, upstream):
    """Use the previous clause marker and the current word's grammatical class."""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip().lower()
    if previous not in {"that", "which"}:
        return None, 0.0

    current = prefix.token_strings[-1].strip().lower()
    if current in PRONOUNS:
        return None, -3.08
    if current in BE_VERBS:
        return None, -1.45
    if current in MODALS:
        return None, -0.99
    if current in ARTICLES:
        return None, -1.08
    if current in AUXILIARIES:
        return None, -1.03
    return None, 0.15

programs.sol:
"""Chat boundaries and relatively uncommon fused text pieces.

For ordinary ASCII tokens, BPE merge-order rank is a rough rarity proxy:
late merges receive a larger response, especially at a word boundary.
Mixed-case identifiers have an additional length-dependent response. Other
scripts use character count instead, which was a better predictor than
applying the ASCII merge-rank formula to these scripts.

Qwen's tokenizer metadata has token ID = 256 + merge-order rank for every
ordinary merged token (the first 256 entries are individual bytes). This
uses that ordering, not a table of learned responses to individual tokens.
"""
import math
import re
import unicodedata

READS = ()
DELIMITERS = {
    '<|im_start|>': 7.3, '<|im_end|>': 4.3, '<|endoftext|>': 1.9,
    '<think>': 6.4, '</think>': 6.15,
    '<tool_call>': 5.0, '</tool_call>': 4.5,
    '<tool_response>': 5.75, '</tool_response>': 7.2,
}
FIRST_DELIMITERS = {
    '<|im_start|>': 3.9, '<|im_end|>': 3.89,
    '<|endoftext|>': 1.57,
    '<tool_call>': 3.28, '</tool_call>': 3.14,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    carry = (doc, position)
    token = prefix.token_strings[-1]
    if token in DELIMITERS:
        value = DELIMITERS[token]
        if position == 0:
            value = FIRST_DELIMITERS.get(token, value)
        elif token == '<|im_end|>':
            value = 5.05 - 0.15 * math.log1p(position)
        return carry, value

    text = token.strip()
    letters = [c for c in text if c.isalpha()]
    n = len(letters)
    if not text:
        value = 0.51 if '\t' in token and ' ' in token else 0.02
        if token == '\r':
            value = 0.93
    elif text.isdigit():
        value = 0.0
    elif any(ord(c) > 127 for c in text):
        names = [unicodedata.name(c, '') for c in letters]
        if names and all('CJK' in name for name in names):
            value = (0.0, 0.1, 0.51, 0.8, 1.8)[min(n, 4)]
        elif names and names[0].startswith('ARABIC'):
            value = min(1.3, 0.23 * (n - 1))
        elif names and names[0].startswith(('HIRAGANA', 'KATAKANA', 'HANGUL')):
            value = min(1.0, 0.06 + 0.2 * (n - 1))
        else:
            value = min(0.6, max(0.01, 0.08 * (n - 2)))
    else:
        # One rank unit is 100,000 BPE merges; this is not token frequency.
        rank = max(0, int(prefix.token_ids[-1]) - 256) / 100000.0
        if re.search('[a-z][A-Z]', text):
            value = 0.76 + 1.2 * rank + 0.15 * (min(len(text), 16) - 1)
        elif text.isalpha():
            if not token.startswith(' '):
                value = -0.04 + 0.55 * rank
            elif text.istitle():
                value = -0.08 + 1.8 * rank
            elif text.isupper() and n > 1:
                value = -0.07 + 1.37 * rank
            else:
                value = -0.03 + 1.6 * rank
        elif letters:
            if text[0] in './_':
                value = -0.03 + 0.92 * rank
            else:
                value = -0.05 + 0.51 * rank
        else:
            value = 0.003 + 0.54 * rank
            if text in {'+=', '-=', '*=', '/=', '%=', '&=', '|=', '^='}:
                value = 0.8
            elif text in {'":"', '","'}:
                value = 0.8
            elif text == '{"':
                value = 0.4
    return carry, float(value)

"""A short alphabetic continuation after an s-like ending.

Respond most strongly after Latin s, Cyrillic с, or Arabic س, and less
strongly after z/x or other sibilant spellings. A one-letter or two-letter
vowel-starting continuation is strongest; longer pieces are weaker.
Short vowel pieces ending in a nasal are boosted; sibilant endings are
reduced. An h-starting piece can extend s to the digraph sh.
Consonant clusters beginning with s or t are nearly silent. These are
averages, not a list of vocabulary tokens or an exact model simulation.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouyıæœøаеиоуыэюяёіїαεηιουωاأإآويیىے')
# Average response by continuation length: 1, 2, 3, 4, 5, 6+ characters.
VOWEL_RESPONSE = (1.8, 1.15, 0.63, 0.24, 0.28, 0.11)
CONSONANT_RESPONSE = (0.88, 0.20, 0.0, 0.0, -0.09, -0.03)


def ending_strength(token):
    token = token.lower()
    last = token[-1:] if token else ''
    if last in ('s', 'с'):
        return 1.0
    if last in ('س', 'ص'):
        return 1.1
    if last in ('σ', 'ς'):
        return 0.5
    if last in ('z', 'з', 'x', 'ſ'):
        return 0.32
    if last and last in 'śšşșžźżшщжξζ':
        return 0.18
    if token.endswith('sh'):
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    strength = carry[1] if carry is not None and carry[0] == doc else 0.0
    value = 0.001
    if strength and token:
        first = unicodedata.normalize('NFD', token[0].lower())[0]
        mark = unicodedata.category(first).startswith('M')
        if first.isalpha() or mark:
            length = min(len(token), 6) - 1
            if first in VOWELS or mark:
                response = VOWEL_RESPONSE[length]
            elif first in 'stс':
                response = 0.16 if length == 0 else 0.0
            else:
                response = CONSONANT_RESPONSE[length]
            response *= 0.96
            if first in VOWELS and 2 <= len(token) <= 3:
                last = token[-1].lower()
                if last in 'mnмн':
                    response += 0.3
                elif last in 'szxсзшщж':
                    response -= 0.25
            if first == 'h':
                response += 0.33
            value += strength * response
    return (doc, ending_strength(token)), float(value)

"""A local plural/agreement detector, especially strong on 'are'.

Only the current and preceding token are used. Plural-looking endings in
English nouns and code identifiers boost plural auxiliaries and collection
operations. Singular auxiliaries receive negative plural corrections.
Subject pronouns, questions and existential 'there' have separate calibrations.
Repeated plural endings get a small negative background correction.
This approximates the large responses, not the many small lexical effects.
"""
READS = ()

IRREGULAR_PLURALS = {'people', 'men', 'women', 'children', 'mice',
                    'teeth', 'feet', 'oxen', 'geese'}
NONPLURAL_S = {'is', 'was', 'has', 'does', 'his', 'its', 'us', 'yes',
              'thus', 'news', 'less', 'business', 'process', 'class'}
COLLECTIVES = {'data', 'criteria', 'phenomena', 'media', 'police', 'cattle'}
MODIFIERS = {'to', 'can', 'could', 'will', 'would', 'should', 'may', 'might',
             'must', 'shall', 'not', "'t", '’t', "'ll", '’ll', 'do', 'also',
             'still', 'just', 'only', 'even', 'already', 'now', 'never', 'always'}
# Calibrated responses for the following 'are', 'were', 'have', respectively.
SUBJECTS = {
    'there': (0.17, 0.01, 0.02),
    'here': (0.33, 0.22, 0.05),
    'what': (-0.04, -0.10, -0.10),
    'how': (0.34, 0.10, 0.00),
    'why': (0.24, 0.10, -0.05),
    'where': (0.44, 0.24, 0.05),
    'i': (0.64, 0.34, -0.01),
    'it': (0.44, 0.07, -0.03),
    'he': (0.53, 0.15, 0.03),
    'she': (0.53, 0.15, -0.03),
    'you': (0.75, 0.46, 0.11),
    'we': (0.80, 0.55, 0.09),
    'they': (0.96, 0.62, 0.32),
    'who': (0.68, 0.37, 0.24),
    'which': (0.80, 0.52, 0.34),
    'that': (0.77, 0.49, 0.29),
    'these': (1.02, 0.63, 0.47),
    'those': (1.17, 0.84, 0.54),
    'both': (1.13, 0.80, 0.44),
}


def plural_strength(word):
    if word in IRREGULAR_PLURALS:
        return 0.75
    return float(word.endswith('s') and word not in NONPLURAL_S
                 and not word.endswith(('ss', 'ous', 'ness')))


def response(token, previous):
    word, prev = token.strip().lower(), previous.strip().lower()
    plural = plural_strength(prev)
    spaced = token[:1].isspace()
    if not spaced and word == 'are':
        # Distinguish a standalone verb from the same spelling inside a word.
        boundary = not previous or not previous[-1:].isalnum()
        return (0.53 if boundary else 0.13) + 0.55 * plural
    if spaced and word in {'are', 'aren', 'were', 'have'}:
        index = {'are': 0, 'aren': 0, 'were': 1, 'have': 2}[word]
        values = (0.64, 0.33, 0.17)
        if prev in SUBJECTS:
            values = SUBJECTS[prev]
        elif plural:
            values = tuple(b + plural * boost for b, boost in
                           zip(values, (0.58, 0.52, 0.47)))
        elif prev in COLLECTIVES:
            values = (0.78, 0.47, 0.23)
        elif prev in MODIFIERS:
            values = (0.73, 0.42, 0.08)
        elif prev in {'and', 'or', 'but', 'as', 'all', 'some'}:
            values = (0.78, 0.47, 0.26)
        elif prev and not any(c.isalpha() for c in prev):
            values = (0.70, 0.39, 0.24)
        return values[index] - (0.36 if word == 'aren' else 0.0)
    if spaced and word in {'is', 'was', 'has', 'does'}:
        return (0.03 if word in {'is', 'does'} else -0.03) - 0.25 * plural
    if spaced and word == 'per':
        return -0.10 + 0.39 * plural
    if spaced and word == 'do':
        return -0.04 + 0.24 * plural
    contraction = token.replace('’', "'")
    if contraction == "'re":
        return 0.21
    if contraction == "'ve":
        return -0.14
    if contraction == "'s":
        return -0.04 - 0.12 * plural
    if token.lower() in {'.push', '.append', '.get', '.add', '.put', '.length',
                         '.map', '.pop', '.insert', '.clear', '.join', '.len',
                         '.count'}:
        return 0.14 + 0.45 * plural
    if token in {'/test', '_test'}:
        return 0.01 + 0.58 * plural
    if token.startswith('['):
        return 0.02 + (0.41 if len(token) <= 2 else 0.13) * plural
    if word in {'list', 'map', 'array', 'count', 'summary'}:
        return 0.04 + (0.53 if spaced else 1.03) * plural
    if (len(token) > 1 and token[0] in './_'
            and token[1:].isascii() and token[1:].isalpha()):
        return 0.18 * plural
    if word.endswith('s') and word.isalpha():
        if not previous:
            return -0.22
        return -0.10 * max(plural, float(prev in {'these', 'those'}))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(token, previous))

"""Strongly recognize 'me', more weakly other English object pronouns.

This is a lexical rather than purely grammatical feature: short word
pieces ending in 'me' and spellings of that syllable also activate it.
The words 'theme', 'mechanism', and 'name' get separate lexical levels;
common rhyming words such as 'time' do not inherit the short-piece rule.
For 'you', conditional clauses are weaker than receiving/helping contexts.
Only the immediately preceding token supplies this grammatical cue.
Unrecognized tokens get zero; their many small responses are not modeled.
"""
READS = ()

OBJECT_PRONOUNS = {'you': 0.72, 'him': 0.92, 'them': 0.32, 'her': 0.07}
ME_SYLLABLES = {'メ': 2.4, 'め': 1.1, '메': 2.3, 'ме': 1.2}
RHYME_VOWELS = {'a': 2.5, 'e': 3.1, 'i': 1.5, 'o': 2.0, 'u': 1.8, 'y': 1.5}
PREPOSITIONS = {'to', 'for', 'with', 'of', 'from', 'at', 'by'}
GIVING_VERBS = {'give', 'gives', 'gave', 'giving', 'tell', 'tells', 'told',
                'telling', 'show', 'shows', 'showed', 'send', 'sent',
                'provide', 'offer', 'teach'}
COMMON_ME_WORDS = {'some', 'same', 'time', 'come', 'home', 'game', 'came'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if lower == 'me':
        value = 3.8 if word == 'Me' else 3.1
        if word == 'me' and token.startswith(' '):
            if previous in PREPOSITIONS:
                value = 2.75
            elif previous in GIVING_VERBS:
                value = 3.6
    elif lower == 'us':
        value = 0.2 if word.isupper() else (0.98 if token[:1].isspace() else 0.1)
    elif lower in OBJECT_PRONOUNS:
        value = OBJECT_PRONOUNS[lower]
        if lower == 'you' and word == 'you':
            if previous == 'if':
                value = 0.10
            elif previous == 'when':
                value = 0.25
            elif previous == 'once':
                value = 0.45
            elif previous in PREPOSITIONS:
                value = 0.96
            elif previous in GIVING_VERBS or previous in {'help', 'helps'}:
                value = 1.25
    elif word in ME_SYLLABLES:
        value = ME_SYLLABLES[word]
    elif lower == 'mes':
        value = 1.6
    elif (len(lower) in (3, 4) and lower[0] in RHYME_VOWELS
          and lower[1:3] == 'me' and lower[3:] in ('', 's')):
        value = RHYME_VOWELS[lower[0]]
        if lower.endswith('s'):
            value *= 0.5 if lower[0] in 'ai' else 0.85
    elif lower in {'theme', 'themes'}:
        value = 1.45 if lower == 'theme' else 1.12
    elif lower in {'mechanism', 'mechanisms'}:
        value = 1.29
    elif lower == 'name':
        value = 0.08 if token[:1].isspace() else 0.28
    elif lower in {'/me', '.me', '-me', '_me'}:
        value = 3.1
    elif (lower not in COMMON_ME_WORDS and lower.endswith('me')
          and len(lower) <= 4 and lower.isalpha()):
        value = 1.0 if not token[:1].isspace() else 0.6
    return (doc, lower), float(value)

programs.haiku:
"""The English pronoun "me" detector for layers.0.mlp.down_proj:3275.

The component writes its signal when the current token is the word "me" in any
capitalisation, with or without a leading space ("Let me", "give me", "ME"): strongest there.
It responds about as strongly to the bare syllable "me" when it is a fragment of a longer
word with no leading space (-ame, -ome, -ume, -ime, -eme, -mes, and "theme"), and to the
Japanese kana め/メ. It does not respond to whole words that merely contain the letters,
such as " time", " name", " home", " same".
It responds more weakly to the other object pronouns " us", " him" and " you" (and
" them" weakly), not to "US" or "her". Everything else is close to zero.
"""

READS = ()

ME_WORD = {" me", " Me", " ME", "me", "Me", "ME"}
ME_FRAGMENT = {"theme", " theme", "Theme", "め", "メ", "ame", "ome", "ume", "ime", "eme", "mes",
               "omes", "umes", "imes", "AME", "IME", "-me"}
OTHER_PRONOUN = {" him": 0.9, " us": 1.0, " you": 0.7, " You": 0.7, "You": 0.7, " them": 0.3}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in ME_WORD:
        value = 3.0
    elif tok in ME_FRAGMENT:
        value = 1.8
    else:
        value = OTHER_PRONOUN.get(tok, 0.0)
    return carry, float(value)

