"""Detect vocabulary about research, science, investigation, and searching.

The noun 'research' has a much larger response than neighboring concepts.
Inflections and scientific occupations have their own strengths. Token casing
and word boundaries matter for 'looking' and 'search'. Related translations
and a few word completions and search/research prepositions are included.
This is a lexical rule, not a judgment about whether the surrounding text
is actually scientific. Unlisted tokens receive zero.
"""
READS = ()


def lexical_value(raw):
    word = raw.strip().lower()
    if word == 'research':
        return 6.6
    if word == 'researcher':
        return 3.7
    if word == 'researchers':
        return 3.35
    if word == 'researching':
        return 4.7
    if word == 'researched':
        return 4.3
    if word in {'scientific', 'scientists', 'scientist'}:
        return 1.9
    if word == 'scientifically':
        return 1.4
    if word in {'science', 'neuroscience'}:
        return 1.1
    if word == 'sciences':
        return 0.65
    if word in {'investigation', 'investig', 'investigative'}:
        return 1.6
    if word in {'investigate', 'investigated', 'investigating',
                'investigations', 'investigator', 'investigators'}:
        return 1.1
    if word == 'experimentation':
        return 1.85
    if word in {'experiment', 'experiments', 'experimenting', 'experimented'}:
        return 1.15
    if word in {'experimental', 'perimental'}:
        return 0.87
    if word in {'academic', 'academics', 'academia', 'scholar',
                'laboratory', 'laboratories'}:
        return 0.85
    if word in {'professor', 'professors', 'findings', 'scholars',
                'scholarship'}:
        return 0.65
    if word in {'testing', 'tested'}:
        return 0.45 if word == 'testing' else 0.15
    if word in {'look', 'looks', 'looked'}:
        return 1.0
    if word == 'looking':
        return 0.58 if raw.strip()[0].isupper() else 0.75
    if word == 'search':
        return 1.7 if raw in {'search', 'SEARCH'} else 1.05
    if word in {'.search', '_search', 'searching', 'searched', 'searches'}:
        return 1.1
    # Translations and common token pieces of research/science vocabulary.
    if word in {'科研', '科学研究'}:
        return 3.5
    if word in {'调研', 'ricerca', 'pesquisa'}:
        return 3.1
    if word == 'recherche':
        return 2.25
    if word in {'研究所', '研究院'}:
        return 1.8
    if word in {'的研究', '研究成果', '学术'}:
        return 1.6
    if word in {'研究', '研', '科学', '科學', '研发', '实验', '实验室',
                '연구', 'forsk', 'fors', 'orsch', 'wissenschaft',
                'issenschaft', 'исслед', 'науч', 'nghiên', 'العلم'}:
        return 1.25
    if word in {'zoek', 'recher'}:
        return 1.5
    if word == 'cherche':
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    value = lexical_value(raw)
    same_document = (len(prefix.token_ids) > 1
                     and prefix.document_ids[-1] == prefix.document_ids[-2])
    if same_document:
        previous = prefix.token_strings[-2].strip().lower()
        # Complete research when it is split into two tokens.
        if raw.lower() == 'search' and previous in {'re', '/re', '-re'}:
            value = 6.6 if raw.isupper() else 5.2
        elif previous == 'research':
            if raw in {'es', 'er', 'ing'}:
                value = 3.4
            elif raw == 'ers':
                value = 2.3
            elif raw in {' of', ' on', ' into', ' in'}:
                prepositions = {' of': 2.6, ' on': 0.9,
                                ' into': 0.65, ' in': 0.25}
                value = prepositions[raw]
        elif previous in {'search', 'searching'}:
            if raw == ' for':
                value = 0.85
            elif raw == ' of':
                value = 0.65
        elif previous == 'experiment' and raw == 'ally':
            value = 0.55
    return None, float(value)

