programs.sol:
"""Sparse lexical approximation: yield/shield, guarding, and 良 ('good').

The response is negative and token-local, with a few one-token continuations.
This is not a general safety or sentiment classifier: it singles out these
spellings, including the shared 'ield' fragment. Japanese よ is an additional
response. Most other tokens receive zero; smaller, unrelated responses are
left unexplained. Previous-token state resets at document boundaries.
"""
READS = ()

GUARDING = {'guard', 'guards', 'guardian', 'guardians', 'marshal',
            'safeguard', 'safeguards'}
FAVORABLE = {'favorable', 'favourable', 'friendly', 'gentle', 'tender',
             'hearty', 'genuine', 'fruitful'}
STRONG_ROOTS = {'yield', 'yields', 'yielded', 'yielding', 'shield',
                'shields', 'shielding', 'ield', 'ields'}


def lexical(token):
    spelling = token.strip().lstrip('_-')
    word = spelling.lower()
    if word == 'yield':
        return -5.0 if spelling == 'Yield' else -4.65
    if word in {'ield', 'ields', 'ielding'}:
        return -4.8
    if word == 'yields':
        return -4.05
    if word in {'yielded', 'yielding', 'shield', 'shields'}:
        return -3.7
    if word == 'shielding':
        return -3.0
    if word in {'shelter', 'shelters', 'guarded'}:
        return -1.4
    if word in GUARDING or word in FAVORABLE or word == 'riendly':
        return -0.7
    if '良' in token:
        if token == '良':
            return -6.3
        # Good-character compounds are weaker; hiragana marks Japanese forms.
        japanese = any('\u3040' <= c <= '\u309f' for c in token)
        return -(1.4 if japanese else 3.0) / len(token)
    if token == '盾':
        return -2.6
    if token in {'防护', '屏蔽'}:
        return -1.05
    if token == 'よ':
        return -2.0
    if token == 'よい':
        return -1.1
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    root = previous.strip().lower()
    value = lexical(token)
    if token in {'ed', 'ing'}:
        if root in {'shield', 'yield', 'ield'}:
            value = -3.1 if token == 'ed' else -2.9
        elif root in {'shelter', 'guard'}:
            value = -1.35 if root == 'shelter' else -0.7
    if root in STRONG_ROOTS:
        value = {' of': -1.6, ' a': -0.5, ' an': -0.5,
                 ' the': -0.35, ' to': -0.4}.get(token, value)
    if token in {' field', ' fields'}:
        if root in {'magnetic', 'radiation'}:
            value = -0.65
        elif root in {'electric', 'electromagnetic', 'force'}:
            value = -0.35
    if previous and '\ufffd' in token:
        if prefix.text_prefixes[-1].endswith('良'):
            value = -6.3
    return (doc, token), value

