"""Lexical mixture: menus, leagues, spectra, with weaker collection/math cues.

Most tokens are near zero. The largest negative responses are specific to
menu, league and spectrum spellings (and selected translations), not to all
words about collections. Related catalog names, membranes and mathematical
pi/ordinal symbols have weaker negative responses. Completing a split Unicode
character can have a different strength from receiving that character whole.
The only remembered context is the preceding token, reset at document changes.
"""

READS = ()

CATALOGS = {'agenda', 'curriculum', 'repertoire', 'portfolio'}
LIST_NAMES = {'inventory', 'alphabet', 'corpus', 'census'}
CULTURAL_COLLECTIONS = {'album', 'albums', 'genre', 'genres', 'museum', 'gallery'}
COMPETITIONS = {'tournament', 'tournaments', 'championship', 'festival'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    word = token.strip().lower()
    bare = word.lstrip('_-/(.')
    split = '\ufffd' in token
    if split:
        completed = prefix.text_prefixes[-1][-1:]
        if completed != '\ufffd':
            word = bare = completed

    value = -0.002
    if bare == 'menu':
        value = -3.3
        if word.startswith('('):
            value = -1.7
        elif word.startswith('_'):
            value = -2.8
    elif bare in {'menus', 'submenu'}:
        value = -2.5
    elif 'menu' in bare:
        value = -1.3  # Compound UI names, e.g. MenuItem.
    elif bare == 'league':
        value = -2.1 if token.startswith(' ') else -1.8
    elif bare == 'leagues':
        value = -1.37
    elif bare in {'spectrum', 'pectrum'}:
        value = -2.35 if token.startswith(' ') else -1.9
    elif bare == 'spectra':
        value = -1.8
    elif bare in {'spectral', 'pectral'}:
        value = -0.95 if bare == 'spectral' else -1.4
    elif bare in {'spect', 'spectro'}:
        value = -0.52
    elif word in {'谱', '譜'}:  # Musical score / spectrum.
        value = -4.35 if split else -3.46
    elif word == '谱写':  # Compose a score.
        value = -2.3
    elif word == '菜单':  # Menu.
        value = -3.03
    elif word == 'メニュー':  # Menu, Japanese.
        value = -1.53
    elif word in {'联赛', '联盟'}:  # League / alliance.
        value = -1.19
    elif word == '盟':  # Alliance.
        value = -1.57
    elif word in {'谋', '謀'}:  # Plan / strategy.
        value = -1.75
    elif word == '菜':  # Dish / vegetable.
        value = -2.25 if split else -0.3
    elif word == '検':  # Inspect.
        value = -0.52
    elif word in {'membrane', 'membranes', '膜'}:
        value = -0.75
    elif bare in {'calendar', 'calendars'}:
        value = -0.8
    elif word in {'recipe', 'recipes', 'playlist', 'playlists', 'memes'}:
        value = -0.57
    elif word in CATALOGS:
        value = -0.65
    elif word in LIST_NAMES:
        value = -0.36
    elif word in CULTURAL_COLLECTIONS:
        value = -0.25
    elif word in COMPETITIONS:
        value = -0.36
    elif bare in {'pi', 'π', '𝜋'}:
        value = -0.38
        if bare == 'pi':
            value = -0.46 if prev.endswith('\\') else -0.2
    elif word in {'º', 'ª'}:
        value = -0.77
    elif split and word == 'ℜ':  # Real part in mathematics.
        value = -1.65

    # A menu may finish in a second token in Russian or Korean.
    if word == 'ю' and prev.lower().endswith('мен'):
        value = -1.05
    elif word == '뉴' and prev.endswith('메'):
        value = -1.05
    return (doc, token), value

"""A negative detector for isolated h/H and short fragments ending in h.

Familiar endings (especially ch, th, ah, oh) respond less than unusual
letter+h combinations. Case and leading whitespace/punctuation modify it;
most longer fragments return zero. Pieces containing height or beginning
with enhanc, and a few single letters in other scripts, also receive
negative values. This is a spelling-based approximation,
not a claim that every token containing h has the same response.
"""
import unicodedata

READS = ()

# Two-letter h endings: common digraphs versus rarer letter combinations.
H_ENDINGS = {
    'ch': -0.08, 'th': -0.65, 'ah': -0.40, 'oh': -0.50,
    'ph': -0.95, 'sh': -1.80, 'eh': -1.55, 'gh': -2.20,
    'hh': -2.10, 'zh': -2.00, 'wh': -2.85, 'kh': -2.75,
    'uh': -2.65, 'äh': -1.35, 'öh': -1.40, 'üh': -0.85,
}
LONGER_ENDINGS = {
    'ch': 0.0, 'th': -0.25, 'ah': -0.65, 'oh': -0.70,
    'eh': -1.30, 'gh': -1.05, 'ph': -0.50, 'kh': -1.30,
}
VOWEL_SH = {'a': 0.04, 'e': -0.95, 'i': -0.65, 'o': -0.80, 'u': -0.90}


def strength(token):
    word = token.strip()
    fragment = word.lstrip('._-/\\(\'"=:+*,;[<{')
    lower = fragment.lower()
    n = len(fragment)
    spaced = token[:1].isspace()
    punctuated = fragment != word
    if lower == 'h':
        if punctuated:
            return -1.30 if fragment == 'H' else -1.50
        if spaced:
            return -1.62 if fragment == 'H' else -1.77
        return -1.92 if fragment == 'H' else -2.38
    if lower.endswith('h') and n >= 2:
        ending = lower[-2:]
        if n == 2:
            value = H_ENDINGS.get(ending, -3.25)
            if ending == 'th':
                value = -0.43 if fragment.islower() and not spaced else -0.95
            elif ending == 'sh' and fragment.isupper():
                value = -1.75 if spaced else -2.50
            elif fragment.istitle():
                if value < -1.7:
                    value += 0.55
                elif ending == 'ph':
                    value += 0.30
            elif fragment.isupper() and ending not in H_ENDINGS:
                value *= 0.80
            if spaced and value < -1.8:
                value += 0.40
        elif n == 3:
            value = LONGER_ENDINGS.get(ending, -2.40)
            if ending == 'sh':
                value = VOWEL_SH.get(lower[0], -0.75)
            elif ending == 'th' and lower[0] == 'i':
                value = -0.65
            elif not lower.isascii() or ending == 'xh':
                value = -0.40
        else:
            rare = lower.isascii() and ending in ('nh', 'ih', 'rh', 'dh')
            value = -1.60 if rare and n <= 5 else 0.0
        return value * (0.75 if punctuated else 1.0)
    if 'height' in lower:
        return -0.72
    if lower.startswith('enhanc'):
        return -1.15
    if lower.startswith('h') and n == 2:
        if lower[1] in 'sx':
            return -0.95
        if lower == 'he' and (spaced or fragment == 'He'):
            return 0.0
        return -0.20 if lower[1] in 'aeiot' else -0.10
    base = ''.join(c for c in unicodedata.normalize('NFD', word)
                   if not unicodedata.combining(c))
    if base in ('η', 'Η'):
        return -0.85
    if base in ('ه', 'х', 'Х'):
        return -0.40
    if base in ('Н', 'н'):
        return -0.20
    return 0.0


def step(carry, prefix, upstream):
    return None, float(strength(prefix.token_strings[-1]))

programs.haiku:
"""Fires negative on short tokens whose last letter is h (h, H, sh, wh, ph, ...), and on Greek eta.
A bare h is the strongest; a consonant+h digraph (sh, ph, wh) somewhat weaker; th/ah/oh weak; ch none."""
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip(" /-._(\"'")
    low = s.lower()
    if s in ("η", "ή"):
        return carry, -0.8
    if not low.endswith("h") or not s.isalpha() or len(s) > 2:
        return carry, 0.0
    if low == "ch":
        return carry, 0.0
    if low in ("th", "ah", "oh"):
        return carry, -0.5
    if len(low) == 1:
        return carry, -2.0
    return carry, -1.8

programs.luna:
"""Mark the standalone English letter names h and H in tokenized text."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    letter = token.strip()
    if letter == "h":
        return None, -2.3
    if letter == "H":
        return None, -1.8
    return None, 0.0

"""Estimate the activation from words comparing amount or degree.

Comparison words receive fixed negative estimates; a few common
continuations (“best of”, “more likely”, “easier to”) get smaller ones.
All other tokens receive zero. The estimates are coarse, not a full match.
"""
READS = ()

MORE = {"more", "mehr", "больше", "более", "更多"}
LESS = {"less", "меньше", "менее"}
ADJECTIVE_COMPARISONS = {
    "best", "better", "worse", "greater", "easier", "bigger",
    "preferable", "лучше", "хуже", "выше", "ниже", "дальше",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ""
    word = prefix.token_strings[-1].strip().lower()
    if word in MORE:
        value = -1.5
    elif word == "weniger":
        value = -0.4
    elif word == "更":
        value = -1.0
    elif word in LESS:
        value = -1.25
    elif word == "easier":
        value = -2.6
    elif word == "greater":
        value = -2.15
    elif word == "bigger":
        value = -1.85
    elif word == "preferable":
        value = -0.8
    elif word in ADJECTIVE_COMPARISONS:
        value = -1.8
    elif word.startswith("лучш"):
        value = -0.75
    elif previous == "best" and word == "of":
        value = -1.0
    elif previous == "more" and word == "likely":
        value = -0.55
    elif previous == "easier" and word == "to":
        value = -0.85
    else:
        value = 0.0
    return (doc, word), value

"""Give negative responses to words naming amounts or measurable qualities.

The sampled strong responses cluster on quantity, size, extent, intensity,
and quality terms, so the rule uses a small vocabulary of those concepts.
"""

READS = ()

AMOUNT_WORDS = frozenset({
    "amount", "amounts", "quantity", "quantities", "size", "sizes",
    "magnitude", "length", "volume", "mass", "weight", "weights",
    "strength", "intensity", "energy", "power", "speed", "age",
    "dose", "doses", "measured", "weighted", "quality", "qualities",
    "metrics", "budget", "batch", "的程度", "程度", "品质", "高质量",
    "功率", "速度", "количество", "lượng", "大量",
})

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,;:!?()[]{}\"'`，。；：！？（）")
    if word not in AMOUNT_WORDS:
        return None, 0.0
    if word in {"quantity", "quantities", "大量"}:
        return None, -4.4
    if word == "volume":
        return None, -2.3
    if word == "lượng":
        return None, -2.6
    if word == "количество":
        return None, -1.25
    if word in {"amount", "amounts"}:
        return None, -1.5
    if word in {"strength", "高质量"}:
        return None, -1.6
    if word == "mass":
        return None, -1.1
    return None, -0.7

programs.sol:
"""Detect packed closing punctuation rather than the words around it.

The largest response is to a quote immediately followed by a comma; preceding
punctuation makes that response stronger. Other closing delimiters and line
endings give smaller responses. Completed split Unicode characters give a
negative response, especially the historical long s (ſ) and fragments whose final UTF-8
byte is BF. A brace after whitespace is treated as a block ending rather than
as an inline delimiter.
"""
READS = ()
QUOTES = '\"\'`”’»'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    s = token.strip()
    newline = '\n' in token
    leading_space = token.startswith(' ')
    value = 0.0

    if s == '\ufffd':
        if len(prefix.document_ids) > 1:
            if prefix.document_ids[-1] != prefix.document_ids[-2]:
                return None, 0.0
        character = prefix.text_prefixes[-1][-1]
        value = 0.0 if character == '\ufffd' else -0.08
        if character != '\ufffd' and character.encode('utf-8').endswith(b'\xbf'):
            value = -0.75
        if character == 'ſ':
            value = -4.0
        return None, value

    if not s or any(ch.isalnum() for ch in s):
        return None, value

    quote_comma = next((i for i in range(len(s) - 1)
                        if s[i] in QUOTES and s[i + 1] == ','), None)
    if quote_comma is not None:
        i = quote_comma
        q = s[i]
        value = 1.62 + 0.10 * (q == "'")
        if q in '”’»`':
            value -= 0.83
        value += 0.05 * newline
        before = s[:i].rstrip('\\')
        if before:
            c = before[-1]
            if c in '.:;':
                value += 1.55 if c in '.:' else 0.80
            elif c in ')]}>':
                value += 0.69
            elif c in '([{':
                value += 0.15
            elif c not in QUOTES:
                value += 0.67
        value -= 0.17 * max(0, sum(c in QUOTES for c in s) - 1)
    elif any(q + ':' in s for q in QUOTES):
        value = 0.72 + 0.26 * ("':" in s) - 0.47 * newline
    elif '</' in s:
        value = 0.96
    elif '*/' in s:
        value = 0.60
    elif any(q in s for q in QUOTES):
        value = 0.32 * any(q + c in s for q in QUOTES for c in ')]}')
        if newline:
            value += 0.24 if s in QUOTES and token.count('\n') == 1 else 0.10
        value += 0.23 * any(q + ';' in s or q + ');' in s for q in QUOTES)
        value += 0.13 * any(q + '.' in s or q + ').' in s for q in QUOTES)
    elif s.startswith('}'):
        previous = ''
        if len(prefix.token_strings) > 1:
            if prefix.document_ids[-1] == prefix.document_ids[-2]:
                previous = prefix.token_strings[-2]
        if s == '}':
            value = 0.50 if newline else 0.65
            if not previous or not previous.isspace():
                value = 0.05
        else:
            value = 0.12 * leading_space + 0.32 * newline + 0.41 * (',' in s)
            value += 0.16 * (',' in s and newline)
    elif ',' in s and not s.startswith(','):
        before = s.split(',')[0]
        if before.endswith(']'):
            value = 0.37
        elif before.endswith(')'):
            value = 0.16
        else:
            value = 0.65
        value += 0.40 * any(g in before for g in ('()', '[]', '{}'))
        value += 0.16 * newline
    elif s == ',':
        value = 0.25 * (token.count('\n') == 1)
    elif s.endswith(':') and s.startswith(('*', '_')):
        value = 0.31
    elif s == '(' and newline:
        value = -0.18
    return None, value

"""A coarse word/character-fragment detector, without word-pair memorization.

Letters abutting earlier letters give an approximate within-word position.
Short continuations, especially Cyrillic and accented Latin fragments, get
positive values; familiar endings and longer pieces are weaker. Combining
marks, unfinished UTF-8 characters, and lone carriage returns have separate
rules. The alphabetic-span count and byte-fragment state reset per document.
Specific words can have much stronger responses than these broad averages.
"""
import unicodedata as ud

READS = ()
LATIN_ENDINGS = set("""
s es ed er ers ing ly ment ments ness less ful tion tions ation ations
ion ions ity ities al ally ous able ible ive ize ise ance ence ant ent
ary or ors ism ist en ar le les re res te tes se ses de des ne nen
ando endo iendo ado ada ados adas ido ida idos idas ique iques
ée ées és ère ía ías ção ções ão ões heit keit lich ung ungen
isch ische ischen chen
""".split())
CYRILLIC_ENDINGS = set("""
а я ы и у ю е о ь й ов ев ей ам ям ах ях ом ем им ым
ой ий ый ая яя ое ее ые ие ого его ому ему ыми ими
ать ять ить еть ет ут ют ит ат ят ают яют ете ите ся сь
л ла ли ло на но ный ная ное ные ной ного ному ным ных ными
ть ти чь ия ие ию ии юю ья ье ьи ью ция ции цию цией
ние ния нию нии
""".split())
CYRILLIC_VOWELS = set('аеёиоуыэюяіїє')
SIBILANTS = set('чщшжцсз')


def response(token, previous, offset):
    if token == '\r':
        return 0.8
    if any(ud.category(c).startswith('M') for c in token):
        return 0.3
    if not offset or not token or not token[0].isalpha():
        return 0.0
    script = ud.name(token[0], '').split()[0]
    word, n = token.lower(), len(token)
    if script == 'LATIN':
        if offset == 1:
            return -0.05
        if token.istitle():
            return 0.0
        base = ''.join(c for c in ud.normalize('NFD', word)
                       if not ud.category(c).startswith('M'))
        vowels = sum(c in 'aeiouy' for c in base)
        if word in LATIN_ENDINGS:
            return 0.03 if token.isascii() else 0.0
        if not token.isascii():
            return 0.4 if vowels == 0 else 0.25
        return 0.13 if vowels <= 1 else (0.04 if n <= 5 else 0.0)
    if script == 'CYRILLIC':
        if offset == 1:
            return 0.15
        vowels = sum(c in CYRILLIC_VOWELS for c in word)
        if word in CYRILLIC_ENDINGS:
            return 0.22 if n <= 2 else -0.07
        if vowels > 1:
            return 0.16 if vowels == 2 else 0.0
        if n <= 2:
            return 0.72 if SIBILANTS.intersection(word) else 0.45
        return 0.34
    if script in ('GREEK', 'ARABIC'):
        return 0.23 if n <= 3 else 0.08
    if script == 'KATAKANA' and 'KATAKANA' in ud.name(previous[-1], ''):
        return 1.3 if token == 'ッ' else (0.2 if n == 1 else 0.07)
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, run, pending = (
        ('', 0, False) if carry is None or carry[0] != doc else carry[1:]
    )
    offset = run if token and token[0].isalpha() else 0
    if '�' in token:
        # Inspect joined decoding only at byte-fragment tokens.
        still_partial = prefix.text_prefixes[-1].endswith('�')
        if token.startswith('ー'):
            value = 0.75  # Japanese long-vowel mark plus a partial character.
        elif token[0].isspace():
            value = 0.0
        else:
            value = 0.5 if pending and still_partial else (
                0.15 if still_partial else 0.1
            )
        pending = still_partial
    else:
        value = response(token, previous, offset)
        pending = False
    tail = 0
    for char in reversed(token):
        if not char.isalpha():
            break
        tail += 1
    run = offset + tail if tail == len(token) else tail
    return (doc, token, run, pending), float(value)

programs.luna:
"""A text-only estimate for a response concentrated on continuing word pieces.

Non-initial Cyrillic, Arabic, Greek and accented-Latin pieces have raised
training averages; word-start tokens tend to be near zero. The estimates do
not try to identify the particular word or its surrounding meaning.
"""
import unicodedata

READS = ()

SCRIPT_VALUE = {
    "CYRILLIC": 0.258,
    "ARABIC": 0.266,
    "GREEK": 0.157,
    "KATAKANA": 0.119,
    "THAI": 0.092,
    "HIRAGANA": 0.025,
    "HANGUL": 0.056,
    "CJK": 0.001,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "�" in token:
        return None, 0.20
    if token[:1].isspace():
        return None, 0.0

    for char in token:
        if not char.isalpha():
            continue
        name = unicodedata.name(char, "")
        for script, value in SCRIPT_VALUE.items():
            if script in name:
                return None, value
        if "LATIN" in name:
            if any(c.isalpha() and not c.isascii() for c in token):
                return None, 0.129
            if any(c.isupper() for c in token):
                return None, 0.006
            return None, 0.038
        return None, 0.0
    return None, 0.0

programs.sol:
"""Predict a dash's immediate continuation, strongest for a following digit.

Negative numbers, ranges and hyphenated identifiers share this local pattern.
A separate space token weakens it; double hyphens and typographic dashes also
promote words. A bar closing a dashed text-table cell gets a stronger response.
Ordinary text receives a near-zero prediction.
"""
READS = ()
DASHES = '-–—−'


def continuation(s, previous):
    """The token immediately following a dash-containing token."""
    t = s.strip()
    dash = previous[-1]
    double = previous.endswith('--')
    spaced = previous.startswith(' ')
    typographic = dash in '–—−'
    if any(ch in DASHES for ch in t):
        return 0.0
    if t.isascii() and t.isdigit():
        value = 1.30
        if t == '0':
            value += 0.48
        elif t == '1':
            value -= 0.14
        if spaced or double or dash == '–':
            value += 0.22
        if dash == '—':
            value -= 0.15
        if any(ch in previous for ch in '([{=,'):
            value += 0.24
        return value
    if not t:
        if s in (' ', '\xa0'):
            return 1.02 if typographic or double else 0.53
        return 0.28 if double or typographic else 0.18
    if t == 'and':
        return 1.60 if typographic else (0.80 if double else 0.57)
    if not any(ch.isalnum() for ch in t):
        if t == '|' and double:
            return 2.30
        if '\\' in t:
            return 1.12
        return 0.95 if double else (0.75 if typographic else 0.37)
    if double:
        return 0.18 if t.istitle() and len(t) > 1 else 0.80
    if typographic:
        if t.isupper() or len(t) == 1:
            return 0.55
        return 0.15 if t.istitle() else 0.25
    if t.isascii() and t.isalpha():
        if len(t) == 1:
            return 0.14 if s.startswith(' ') else 0.48
        if t.isupper():
            return 0.10
        if t.istitle():
            return -0.08
        return 0.02 if s.startswith(' ') else -0.14
    return -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = 0.002
    if previous and previous[-1] in DASHES:
        value = continuation(s, previous)
    elif previous == ' ' and before and before[-1] in DASHES:
        value = 0.48 * continuation(s, before)
    return (doc, s, previous), float(value)

programs.luna:
"""Estimate the line-break signal from the current token. A single newline
gets a positive baseline, while a blank-line token gets a negative one; the
line's start, ending, and nearby mark make small adjustments."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    breaks = token.count("\n")

    value = 0.0
    if breaks == 1:
        value = 0.151
    elif breaks >= 2:
        value = -0.249

    # A slash right before one newline is a notably different line ending.
    if token.endswith("/\n"):
        value -= 0.305
    if token.startswith("\n"):
        value += 0.081
    if token.endswith("\n"):
        value -= 0.097
    if token.endswith((" \n", " \n\n")):
        value -= 0.039
    if len(token) >= 2 and token.endswith("\n") and token[-2] in ".,!?:;)]}":
        value += 0.138
    return None, value

programs.sol:
"""A lexical FIND feature, with stronger responses in searching expressions.

Find and its inflections, code lookups, and several translations are the main
triggers. Related actions (looking, checking, obtaining) fire more weakly.
'For' has a small ordinary response but a large one in 'looking/searching for'.
The last two tokens distinguish these phrases and 'trying to find' from 'we find'.
This approximates surface vocabulary, not whether something is actually found.
"""
READS = ()

FIND_FORMS = {
    'find': 3.8,
    'found': 2.2,
    'finding': 3.6,
    'finds': 2.4,
    'findings': 1.2,
    'finder': 1.8,
    'finders': 1.8,
}
# These are written forms of finding, seeking or encountering in other languages.
TRANSLATIONS = (
    (7.6, {'找'}),
    (5.3, {'寻找', '找个', '来找', '去找'}),
    (4.8, {'找到', '找到了', '找了'}),
    (4.0, {'找出', '查找', '找准', '寻'}),
    (3.3, {'尋', '探し', 'tìm'}),
    (2.7, {'найти', 'encontr', 'trovare'}),
    (2.0, {'найд', 'gefunden', 'trouver', 'encontrar', 'busc', 'หา', 'พบ'}),
    (1.7, {'finden', 'finde', 'trouve', 'trouvé', 'cherche',
           'busca', 'buscar', 'trov'}),
    (1.1, {'findet', 'наход', '发现', '遇', '遇到', '求', '求め',
           'を見', 'rencontre'}),
)
RELATED = (
    (1.8, set('locate locating'.split())),
    (0.9, set('''seek seeking sought discover discovers discovered discovering
        discovery'''.split())),
    (0.75, set('missing missed miss lookup'.split())),
    (0.6, set('''look looks looking check checks checked checking located reach
        reaches reached reaching await awaiting encounter encountered detect
        detected detection identify identified identifying retrieval retrieve
        retrieves determine determining'''.split())),
    (0.45, set('''get obtain obtaining choose choosing access view views ask
        asks asked asking buy pick'''.split())),
)
SEARCH_FOR = {
    'looking': 3.8, 'look': 3.3, 'looks': 3.0, 'looked': 2.5,
    'searching': 3.1, 'search': 2.4, 'searches': 1.8, 'searched': 1.65,
    'waiting': 1.5, 'asking': 1.5,
    'wait': 1.1, 'waits': 1.2, 'ask': 1.0, 'asks': 1.2,
    'solve': 1.15, 'solving': 1.2, 'check': 0.9, 'checking': 1.1,
}
NONSEARCH_FOR = set('''used responsible known suitable necessary required
    designed provided needed useful important'''.split())


def word_value(raw, word):
    if word in FIND_FORMS:
        if raw == '.find':
            return 4.85
        if word == 'found' and raw.strip() != 'found':
            return 1.5
        if raw == 'finding':
            return 2.6
        return FIND_FORMS[word]
    if 'notfound' in word:
        return 2.3
    lookup_suffixes = ('by', 'one', 'all', 'view', 'first', 'element', 'orfail')
    if word.startswith('find') and word[4:].startswith(lookup_suffixes):
        return 2.6                 # findById, findAll, findViewById, etc.
    if word.startswith('get') and raw.lstrip().startswith('.'):
        return 0.8 if word == 'get' else 1.0
    if word in {'get', 'view'} and not raw.startswith(' '):
        return 0.6
    if word == 'no':
        return 0.5
    for value, words in RELATED + TRANSLATIONS:
        if word in words:
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, earlier = carry[1:] if carry and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('._(/[-').lower()
    value = word_value(raw, word)
    if word == 'for':
        value = SEARCH_FOR.get(previous, 0.4)
        if raw.strip() in {'For', 'FOR'}:
            value = 0.6
        elif previous in NONSEARCH_FOR:
            value = -0.08
    elif word == 'find' and raw.startswith(' '):
        if raw.strip() == 'Find':
            value = 3.4
        elif previous == 'we':
            value = 2.7
        elif previous == 'to':
            effort = earlier in {'try', 'trying', 'looking', 'easy', 'hard'}
            value = 5.4 if effort else 4.05
        elif previous == 'cannot':
            value = 4.8
    elif word == 'finding':
        if previous in {'of', 'to', 'in', 'for'}:
            value = 4.1
        elif previous in {'this', 'a', 'the', 'these'}:
            value = 2.8
    return (doc, word, previous), float(value)

programs.haiku:
"""Searching and finding words.

The component fires on words that mean "find / look for / locate": 'find' and its forms
(find, Find, finding, finds, .find), 'found', and the Chinese 找 / 寻找 family. Its strongest
response is to 'find' (about 3.5-4). 'found' gives about 2.2. The word 'for' gets a small
baseline response, and a strong one (about 3) when it follows a seeking verb such as
'look', 'searching', 'search', 'wait' or 'ask' ("looking for"). Other tokens get 0.
"""

READS = ()

FIND = {" find", " Find", "find", "Find", " finding", " Finding", " finds", ".find",
        "finding", "finds", "Finder", "findings", " findings"}
FIND_CN = {"找", "寻找", "找到", "找出", "来找", "找个", "寻", "尋", "找到了"}
FOUND = {" found", " Found"}
FOR = {" for", "for", " For", "For"}
SEEK_VERB = {" look", " looking", " Look", "Looking", " search", " searching", " seek",
             " seeking", " wait", " waiting", " Wait", "Wait", " ask", " asking", " asks"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok in FIND or tok in FIND_CN:
        return carry, 3.5
    if tok in FOUND:
        return carry, 2.2
    if tok in FOR:
        return carry, 3.0 if prev in SEEK_VERB else 0.4
    return carry, 0.0

programs.luna:
"""Predicts a lexical response to find/location words and to 'for'."""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "for":
        value = 0.48
    elif word in {"find", "found", "finding"}:
        value = {"find": 3.9, "found": 2.3, "finding": 3.1}[word]
    elif word == "located":
        value = 0.66
    elif word == "check":
        value = 0.55
    else:
        value = 0.00697
    return None, value

programs.sol:
"""Lexical time vocabulary with local phrase modulation.

The negative signal is strongest for spellings of 'time', selected
translations, and identifiers ending in 'Time'. It is weaker in
idioms such as 'first time', 'same time', and 'long time'. Derived words
and word fragments receive smaller signals. 'time to' and 'time of'
have small, opposite-signed signals on their prepositions. Everything
else is zero; diffuse weak token-specific effects are not reproduced.
"""
READS = ()

# Translations of 'time', grouped by approximate response strength.
TIME_TRANSLATIONS = {
    'время': -2.1, 'времени': -2.1, 'zeit': -2.0, 'czas': -2.0,
    'tiempo': -1.8, 'tijd': -1.5, 'zaman': -1.6, 'waktu': -2.6,
    'temps': -0.95, 'tempo': -0.7, 'saat': -0.75, 'thời': -1.0,
    'タイム': -2.3,
}


def time_phrase(previous, before):
    if previous in {'first', 'same', 'long', 'longer', 'hard'}:
        return -0.9
    if previous in {'short', 'some'}:
        return -1.5
    if previous in {'any', 'every', 'next'}:
        return -2.1
    if previous in {'over', 'last', 'one', 'each'}:
        return -2.6
    if previous in {'this', 'that'}:
        return -2.1 if before in {'at', 'during'} else -3.6
    if previous in {'the', 'a'}:
        return -3.3 if before == 'at' else -4.9
    if previous == 'of':
        weak_of_time_context = {'period', 'periods', 'duration', 'length', 'ahead'}
        return -3.0 if before in weak_of_time_context else -4.6
    if previous in {'more', 'much', 'less', 'no', 'all', 'at', 'real', 'second',
                    'limited', 'take', 'takes', 'spend', 'spent', 'spending'}:
        return -3.8
    if previous in {'in', 'on', 'with', 'by', 'as', 'and'}:
        return -5.5
    return -5.0


def response(token, previous, before):
    text = token.strip()
    word = text.strip('._-/(*=,\"\'').lower()
    if token == ' time':
        return time_phrase(previous, before)
    if word == 'time':
        if text.startswith('-'):
            if previous in {'first', 'long', 'short'}:
                return -1.5
            return -2.7 if previous == 'real' else -4.4
        if token == 'Time':
            return -5.6
        return -4.9 if text == 'Time' else -4.4
    if '时间' in text or '時間' in text or '시간' in text:
        return -4.2
    if word in TIME_TRANSLATIONS:
        return TIME_TRANSLATIONS[word]
    if 'datetime' in word:
        return -3.7 if token == ' datetime' else -2.8
    if word in {'timespan', 'timeunit'}:
        return -3.3
    if word in {'timezone', 'timeframe'}:
        return -2.5
    if 'timestamp' in word or word == 'timedelta':
        return -1.7
    if text.endswith('Time'):
        return -4.1
    if word == 'times':
        return -0.55 if token == 'times' else -1.7
    if word in {'timing', 'timed', 'timer', 'timeline',
                'timelines', 'timetable'}:
        return -1.3
    if word in {'while', 'timeout', 'timeouts', 'timely',
                'longtime', 'sometime'}:
        return -0.9
    if word in {'clock', 'clocks', 'deadline'}:
        return -1.0
    if word in {'duration', 'runtime', 'lifetime', 'anytime',
                'daytime', 'timers'}:
        return -0.7
    if word in {'overtime', 'downtime'}:
        return -1.3
    if word == 'timeless':
        return -1.8
    if word in {'ime', 'tim', 'imers', 'imes', 'etime', 'etimes'}:
        return {'ime': -1.4, 'tim': -1.3, 'imers': -0.8, 'imes': -0.5,
                'etime': -3.0, 'etimes': -1.6}[word]
    if word in {'day', 'days', 'seconds', 'hour'}:
        return -0.35
    if previous == 'time':
        if word == 'to':
            return 0.65
        if word == 'of':
            return -0.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, before)
    return (doc, token.strip().lower(), previous), value

programs.haiku:
"""Time words: the activation goes strongly negative on the word 'time' (and compounds such
as createTime, '-time', '时间'), and less so on plurals, clock and timestamp words. In set
phrases such as 'the first time', 'the same time' or 'a long time' it is weak."""
import re

READS = ()
SET_PHRASE_BEFORE = {"first", "same", "long", "short", "some", "every", "each", "next", "last"}
TIME_CJK = ("时间", "時間", "시간", "タイム", "времени")
STRONG_COMPOUND = {"datetime", "timestamp", "_datetime"}
MILD = {"times", "timing", "timer", "timeout", "timeline", "timed", "timely", "timeframe",
        "while", "clock", "microseconds", "day", "days"}

def pieces(s):
    s = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", s)
    return [p for p in re.split(r"[^A-Za-z]+", s.lower()) if p]

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    w = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    words = pieces(raw)
    if any(c in raw for c in TIME_CJK):
        base = -4.0
    elif "time" in words:
        base = -4.5
    elif w.strip("_") in STRONG_COMPOUND or "datetime" in w or "timestamp" in w:
        base = -3.5
    elif "times" in words or w in MILD:
        base = -1.0 if w in ("day", "days") else -1.5
    else:
        return None, 0.0
    if prev in SET_PHRASE_BEFORE and base <= -3.0:
        base = -1.0
    return None, base

programs.sol:
"""A weighted lexical detector for magnitude, totality, and defaults.

Max/maximum/default and 大 ('big') receive the largest predictions.
Selected size, rank, growth and aggregate-quantity words receive smaller
ones; unlisted tokens normally receive zero. This detects token cues, not
sentence meaning. Three short continuations (maximum of, at most, and
maxim- suffixes) use the previous token, resetting at document boundaries.
Split Unicode characters are recognized when their final fragment arrives.
"""
READS: tuple[str, ...] = ()

# Size, upward comparisons, and prominence.
MAGNITUDE = {
    'large': 1.5, 'larger': 1.7, 'largest': 2.0, 'largely': 1.0,
    'big': 0.6, 'bigger': 0.6, 'biggest': 1.1,
    'high': 0.95, 'higher': 1.0, 'highest': 1.4,
    'height': 0.65, 'heights': 0.6, 'peak': 1.0,
    'major': 1.35, 'majority': 1.45, 'dominant': 1.0,
    'great': 0.5, 'greater': 0.8, 'greatest': 0.85, 'greatly': 0.8,
    'grand': 0.9, 'super': 0.85, 'supreme': 0.8, 'macro': 0.9,
    'top': 0.5, 'master': 0.7, 'primary': 0.55,
    'increase': 0.8, 'increases': 0.8, 'increased': 0.7,
    'increasing': 0.6, 'exceed': 1.25, 'exceeds': 1.45,
    'exceeded': 1.45, 'exceeding': 1.2, 'enlarged': 0.9,
    'longer': 0.45, 'longest': 1.1, 'upper': 0.4, 'peaks': 0.8,
    'magn': 0.7, 'magnitude': 0.45, 'magnitudes': 0.45,
    'adult': 0.7, 'adults': 0.7, 'excessive': 0.75,
}
# Broad quantity, aggregate or representative values.
QUANTITY = {
    'all': 0.75, 'always': 0.85, 'many': 0.67,
    'most': 0.95, 'mostly': 0.97, 'total': 0.75,
    'everyone': 0.72, 'everything': 0.45, 'global': 0.63,
    'universal': 0.55, 'widespread': 0.85,
    'average': 0.98, 'averaged': 0.9, 'capacity': 0.62,
    'basic': 0.85, 'exactly': 0.65, 'full': 0.25,
    'first': 0.18, 'only': 0.14,
    'smallest': 0.37, 'shortest': 0.38, 'lowest': 0.34,
    'minimum': 0.28,
    'less': -0.16, 'little': -0.16, 'whole': -0.1,
    'multiple': -0.17, 'enough': -0.29,
    'median': 0.65, 'plurality': 0.53, 'mainly': 0.33,
    'infinity': 0.5, 'infinite': 0.33,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ''
    if same_document and '�' in raw:
        completed = prefix.text_prefixes[-1][-1:]
        if completed != '�':
            raw = completed
    token = raw.strip().lstrip('._/([{=:-')
    word = token.lower()
    value = MAGNITUDE.get(word, QUANTITY.get(word, 0.0))
    if word == 'max':
        value = 4.0 if token == 'Max' else 3.6
    elif word == 'maximum':
        value = 3.0 if token[0].isupper() else 3.6
    elif word == 'maximal':
        value = 2.55
    elif word.startswith('maxim'):
        value = 3.1 if word in {'maximize', 'maximizing'} else 2.7
    elif word.startswith('max'):
        value = 2.3
    elif word in {'default', 'defaults'}:
        value = 2.6 if token.isupper() else 3.4
        if word == 'defaults':
            value -= 0.3
        elif raw == 'default':
            value = 4.0
    elif word.startswith('default'):
        value = 2.1
    elif word in {'university', 'universities'}:
        value = 0.8
    elif word.startswith('максим'):
        value = 2.5
    elif word.startswith(('больш', 'groß', 'größ')):
        value = 0.9
    elif word in {'grande', 'grandes', 'grandi'}:
        value = 0.7
    elif token == '大':
        value = 3.45
    elif '大' in token:
        if token in {'最大', '最大的', '的大', '大的', '大多', '大全'}:
            value = 2.9
        elif token in {'大学', '大學', '大概'}:
            value = 2.4
        elif token in {'大家', '为大家', '大量', '大小', '大陆', '大力', '重大'}:
            value = 0.9
        else:
            value = 1.7 if token.startswith('大') else 1.3
    elif token in {'高', '高的', '全', '总', '總', '全国', '峰'}:
        value = 1.0
    elif token in {'多', '超', '全部', '很多人', '全球', '巨', '太'}:
        value = 0.65
    elif token == '最高':
        value = 1.5
    elif token == '默认':
        value = 2.3
    elif token == '대':
        value = 2.0
    # Bounds and magnitude expressions sometimes continue into the next token.
    if word == 'of' and previous in {'max', 'maximum', 'default'}:
        value = 1.35
    elif word == 'most' and previous == 'at':
        value = 1.5
    elif previous == 'maxim' and word in {'ized', 'izes', 'izing', 'ise', 'ization'}:
        value = 2.0
    elif word == 'all' and raw == 'all':
        value = 0.4
    return (doc, word), float(value)

"""Recognize short sk spellings, 'such', and a separate recency word group.

The negative response is strongest on ask/risk/disk/desk/mask/task forms and
short sk fragments. Inflections and longer spellings usually weaken it.
A one-token memory detects s+k split across tokens and attached suffixes.
Related short sibilant fragments have smaller negative responses.
Selected Cyrillic/Japanese fragments and Chinese word equivalents are included.
Everything outside these groups predicts zero. Coefficients are fitted sizes.
"""
import re

READS = ()
SK_WORDS = {
    'ask': -3.0, 'risk': -2.9, 'disk': -3.5,
    'desk': -3.3, 'mask': -3.7, 'task': -1.8,
}


def response(token, previous):
    word = token.strip().lower()
    spaced = token[:1].isspace()
    plain = word.lstrip('_./-')
    if word == 'such':
        return -0.95
    for root, value in SK_WORDS.items():
        if plain in (root, root + 's', root + 'ed', root + 'ing'):
            if root == 'ask' and not spaced and token.islower():
                value = -5.3
            factor = 0.7 if plain.endswith(('ed', 'ing')) else 1.0
            if plain == root + 's':
                factor = 0.85
            return value * factor * (0.85 if token.startswith('_') else 1.0)
    if word in ('ed', 'ing', 'er') and 'sk' in previous:
        weight = {'ed': 0.65, 'ing': 0.35, 'er': 0.15}[word]
        return weight * response(previous, '')
    if word == 'isk':
        return -5.7 if token.islower() else -4.8
    if word in ('iska', 'iske', 'usk', 'esk'):
        return -2.5
    if word == 'sk':
        return -1.55 if spaced else (-2.05 if token.islower() else -1.65)
    if word.endswith('sk'):
        return -2.1 if not spaced else -1.65
    if 'sk' in word:
        if word.startswith('skip') or word == 'skills':
            return -0.2 if word.startswith('skip') else -0.3
        if word in ('ski', 'skiing', 'skull', 'skew', 'sky'):
            return -1.0
        return -0.6 if len(word) <= 6 else -0.25
    if word in ('иск', 'риск', 'диск', 'スク'):
        return -1.8 if word == 'スク' else -2.4
    if word == 'ск':
        return -0.6 if spaced else -1.55
    # Short Cyrillic adjective fragments with the ск spelling.
    if not spaced and re.fullmatch(
        r'ск(?:а|ая|и|ие|ий|им|их|ого|ое|ой|ом|ую)', word
    ):
        return -0.6
    if plain in ('disc', 'isc', 'asc', 'usc', 'fusc', 'desc', 'esc', 'osc'):
        return -0.6 if plain in ('desc', 'esc', 'osc') else -1.0
    if word in ('ish', 'ism', 'uch', 'asm', 'seek'):
        return -0.55 if word in ('asm', 'seek') else -0.27
    if word.startswith('isch'):
        return -0.75 if len(word) == 4 else -0.42
    if not spaced and word[:1] in ('k', 'к') and word.isalpha() and len(word) <= 3:
        if previous[-1:] in ('s', 'с'):
            if len(word) == 1:
                return -1.3 if word == 'k' else -0.9
            return -2.3 if word == 'ks' else -0.8
        if previous[-1:].isalpha():
            return -0.4 if word == 'k' else -0.2
        return 0.08 if token in ('K', 'к', 'К') else -0.05
    if plain == 'latest':
        return 1.45 if spaced else 0.8
    if word == 'recent':
        return 0.85 if token == ' recent' else 0.3
    if word in ('contemporary', '最新', '最新的', '当代', '近期'):
        return 0.55 if word == '近期' else 0.85
    if word in ('风险', '風險', '的风险'):
        return -2.0
    if word in ('任务', '任務', '的任务', '盘', '碟', '险'):
        return -1.0
    if word in ('问', '問', '提问', '询问'):
        return -0.65
    return 0.0


def step(carry, prefix, upstream):
    document, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    return (document, token.lower()), response(token, previous)

programs.luna:
"""Approximate the activation from spelling and a few word families in the current token.

In training, “such,” ask/task/risk words, and mask words had strong negative responses.
The “isk” fragment and other sk endings often responded negatively too; recentness words
showed a smaller positive response. This ignores surrounding context and otherwise predicts zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    bare = token.strip()

    if "such" in token:
        value = -0.95
    elif bare == "isk":
        value = -5.5
    elif any(word in token for word in ("risk", "風險", "风险")):
        value = -3.0
    elif any(word in token for word in ("task", "任务", "任務")):
        value = -1.6
    elif "mask" in token:
        value = -3.5
    elif "ask" in token or "問" in token:
        value = -2.3
    elif bare.endswith(("sk", "ск")):
        value = -1.9
    elif "sk" in token or "ск" in token:
        value = -1.5
    elif any(word in token for word in ("latest", "recent", "contemporary")):
        value = 0.9
    else:
        value = 0.0

    return None, float(value)

programs.sol:
"""Approximate the component's dominant positive 'ext' spelling response.
Bare ext/xt fragments, extent, extensive, extension, external, and extreme
forms have different strengths; attached punctuation and capitalization matter.
Remember one preceding piece for split ext-words and for 'extent/extension of'.
Other spellings receive zero. This omits smaller unrelated lexical responses.
"""
READS = ()
DELIMITERS = " \t\r\n._-/\\('`\""


def word_response(word):
    if word == 'ext':
        return 5.1
    if word == 'xt':
        return 1.5
    if word.startswith('extensiv'):
        return 2.2 if word.endswith('ly') else 3.1
    if word.startswith('extent'):
        return 2.3 if word.endswith('s') else 3.3
    if word.startswith('extend'):
        return 1.8 if word == 'extend' else 1.6
    if word.startswith('extension'):
        return 1.6 if word.endswith('s') else 1.8
    if word.startswith('extinct'):
        return 2.0 if word.endswith('ion') else 1.7
    if word.startswith('extern'):
        if word == 'extern':
            return 0.8
        return 0.7 if word.endswith('ly') else 1.35
    if word == 'exter':
        return 2.5
    if word.startswith('exterior'):
        return 1.3
