EXTENT_WORDS = {"extent", "extensive", "extensively"}
EXTENT_VALUE = 3.0
OTHER_EXT_VALUE = 1.5
WEAK_PREFIXES = ("extra", "extrac")  # extra, extract, extraction, ...
WEAK_VALUE = 0.3
SPLIT_VALUE = 1.5    # letters continuing a split "ext" word
OF_AFTER_EXTENT = 1.8


def _word(text):
    """Lowercase letters only: " Extent," -> "extent"."""
    return "".join(ch for ch in text.lower() if ch.isalpha())


