    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    word, prev_word = _word(cur), _word(prev)
    if word == "ext":
        value = BARE_EXT
    elif word.startswith("ext"):
        if word in EXTENT_WORDS:
            value = EXTENT_VALUE
        elif word.startswith(WEAK_PREFIXES):
            value = WEAK_VALUE
        else:
            value = OTHER_EXT_VALUE
    elif prev_word == "ext" and word and not cur.startswith(" "):
        value = SPLIT_VALUE
    elif prev_word == "extent" and cur == " of":
        value = OF_AFTER_EXTENT
    else:
        value = 0.0
    return carry, float(value)

