           '「': -0.7, '『': -0.7, '“': -0.5, '《': -0.5,
           '«': -0.33, '‘': -0.33, '„': -0.33}


def parenthesis(p, spaced):
    if not p:
        return -2.35
    word = p.lstrip('.\\')
    if word.lower() in CONTROL_WORDS:
        return -2.0 if spaced else -1.35
    if not spaced:
        if word in MATH_FUNCTIONS or p[-1].isdigit() or p[-1] in ')]}':
            return -1.6
        return -2.65 if not p.isascii() else -1.95
    if word.lower() in ('is', 'are', 'be', 'and', 'or'):
        return -2.25
    if word.lower() in FUNCTION_WORDS or p[-1].isdigit():
        return -2.55
    if any(c in p for c in '=+−'):
        return -1.75
    if any(c in p for c in ')]}') and p[-1] in ',:;.':
        return -1.8
    if not p[-1].isalnum():
        if p[-1] in '"”»':
            return -3.1
        return -2.65 if p[-1] in '.%$`' else -2.2
    if len(p) == 1 or p.isupper():
