    doc = prefix.document_ids[-1]
    last = carry[1] if carry is not None and carry[0] == doc else None
    token = prefix.token_strings[-1]
    s = token.strip()
    p = ''
    if prefix.position and prefix.document_ids[-2] == doc:
        p = prefix.token_strings[-2].strip()
    value = OPENERS.get(s, 0.0)
    if s == '(':
        value = parenthesis(p, token.startswith(' '))
        if token.startswith(' '):
            gap = 1000 if last is None else prefix.position - last
            value += -0.35 + 0.75 / (1.0 + gap / 25.0)
    elif s == '"' and token.startswith(' '):
        value = -0.45 if p and (p[-1].isalnum() or p[-1] == '.') else 0.0
        if p in (',', ':'):
            value = -0.3
    elif s in ('(\\', '[\\', '{\\'):
        value = {'(': -2.1, '[': -0.66, '{': -0.62}[s[0]]
    elif len(s) > 1 and s[-1] in '([{':
        if not any(c.isalnum() for c in s[:-1]):
            value = {'(': -1.1, '[': -0.8, '{': -0.65}[s[-1]]
            if '\\' in s[:-1]:
                value = -0.55
            if ')' in s[:-1] or '}' in s[:-1] or ']' in s[:-1]:
                value = {'(': -0.6, '[': 0.0, '{': -0.2}[s[-1]]
