PAREN = {" (": -3.0, "(": -1.9, "（": -2.8}
# Square brackets.
SQUARE = {" [": -1.2, "[": -1.0, "【": -1.0}
# Curly braces and Japanese/Chinese corner brackets.
CURLY = {" {": -0.7, "{": -0.75, "「": -0.7, "『": -0.65}
# Opening quotes, pipes, dashes and double angle brackets: weak.
QUOTE = {' "': -0.16, " “": -0.5, "“": -0.45, " |": -0.43, "|": -0.3,
         "《": -0.5, " ‘": -0.36, " –": -0.24}

OPENERS = {**PAREN, **SQUARE, **CURLY, **QUOTE}


def step(carry, prefix, upstream):
    # The token being predicted for is the newest one; its decoded text tells us
    # whether it is an opener.
    token = prefix.token_strings[-1]
    return carry, float(OPENERS.get(token, 0.0))

