import re

READS = ()
COMMON_ENDINGS = frozenset(
    's es ed ing ers est ly ion ions ation ations tion tions'.split()
)
CAUSATIVE_ENDINGS = frozenset(('ify', 'ize', 'ise'))

# Offset, continuation gain, and gain per preceding character.
GAINS = {
    'other': (-0.002, -0.002, 0.001),
    'weak': (-0.003, -0.044, 0.005),
    'long': (-0.006, -0.047, 0.009),
    'three': (0.003, -0.08, 0.025),
    'two': (0.054, -0.029, 0.032),
    'one': (0.051, -0.033, 0.041),
    'i_pair': (0.03, -0.015, 0.063),
    'y': (0.038, -0.049, 0.102),
}
SHORT_GROUPS = frozenset(('one', 'two', 'three', 'i_pair', 'y'))


def spelling_group(text):
    if not (text.isascii() and text.isalpha()):
        return 'other'
    n = len(text)
    if text in COMMON_ENDINGS:
        return 'weak'
    if n <= 3 and text.startswith('y'):
        return 'y'
    if 1 < n <= 4 and text[0] == 'i' and text[1] in 'aeiou':
        return 'i_pair'
    if text[0] in 'aeiou':
        return {1: 'one', 2: 'two', 3: 'three'}.get(n, 'long')
    return 'weak'


