    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text = token.lower()
    group = spelling_group(text)
    short = group in SHORT_GROUPS
    value, joined, per_character = GAINS[group]
    if token[:1].isupper():
        value += -0.054 if short else (
            -0.013 if group == 'other' else 0.0
        )
    if previous and previous[-1].isascii() and previous[-1].isalpha():
        length = min(len(previous.strip()), 8)
        runs = min(len(re.findall('[aeiouy]+', previous.lower())), 3)
        final_vowel = previous[-1].lower() in 'aeiouy'
        final_h = previous.lower().endswith('h')
        fragment = previous.isascii() and previous.isalpha()
        value += joined + per_character * length
        if short:
            value += 0.088 * fragment + -0.097 * final_h
            if group == 'one':
                value += -0.035 * runs + 0.145 * final_vowel
            elif group == 'i_pair':
                value += -0.151 * final_vowel + -0.091 * final_h
            elif group == 'y':
                value += 0.113 * runs + -0.312 * final_vowel
                value += -0.352 * final_h
            else:
                value += 0.022 * runs
        elif group != 'other':
            value += 0.02 * fragment
        if len(text) <= 4 and text.isalpha() and text.endswith('ry'):
            value += -0.069 + 0.057 * length
        if text in CAUSATIVE_ENDINGS:
            value += 0.135
        if text == 'ency':
            value += 0.202
    return (doc, token), float(value)

