    acute = (any(c in MODERN_GREEK_TONOS_VOWELS for c in text)
             if greek else "\u0301" in marks)
    spaced = bool(token) and token[0].isspace()
    vowels = sum(c in GREEK_VOWELS for c in base)
    return text, greek, latin, acute, bool(marks), spaced, vowels


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, age, vowels_seen, crossed = "", 0, 0, False
    else:
        _, previous, age, vowels_seen, crossed = carry
    token = prefix.token_strings[-1]
    # Recover a character when this token completes a split UTF-8 encoding.
    if "\ufffd" in token:
        before = prefix.text_prefixes[-2] if prefix.position else ""
        token = prefix.text_prefixes[-1][len(before.rstrip("\ufffd")):]
    text, greek, latin, acute, accented, spaced, vowels = properties(token)
    (prev, prev_greek, prev_latin, prev_acute,
     prev_accented, prev_spaced, _) = properties(previous)
    value = CLOSING_MARKERS.get(text, 0.0)
    if text == "<|im_end|>":
        value = MESSAGE_END.get(previous, 1.10)
    if greek and text.islower():
        if accented:
            value = TONOS_VALUE.get(text, 0.60) if acute else -0.13
        elif spaced or not prev_greek:
            value = -0.07 + {1: 0.87, 2: 0.34}.get(age, 0.0)
        else:
            value = GREEK_BASE.get(text, -1.07)
            if crossed:
                value += {2: 1.36, 3: 0.42}.get(age, 0.0)
            elif 1 <= age <= 3:
                kind = (3 if text == "ς" else
                        0 if text in {"μ", "ν"} else
                        2 if vowels else 1)
                value += TRAIL[age - 1][kind]
                value -= (0.0, 1.38, 1.06)[age - 1] * min(vowels_seen, 2)
