        final_marks = ud.normalize("NFD", prev[-1])
        if any(ud.combining(c) for c in final_marks):
            strength = 1.01 + 0.33 * prev_spaced if prev_acute else 0.21
            value = strength * 0.65 ** (min(len(text), 12) - 1)
    if greek and acute:
        age, vowels_seen, crossed = 1, 0, False
    else:
        if age:
            age += 1
        if greek:
            vowels_seen += vowels
        if spaced or not greek:
            crossed = True
    return (doc, token, age, vowels_seen, crossed), float(value)

