"""Detect words for extending duration, length, or scope.

Forms of 'extend' and 'extension' dominate. Related expansion, continuation,
delay, stretching and modification words give smaller responses. Split
word pieces are recognized from the preceding token. A following 'the',
'of' or 'to' can retain part of the response. 'Extends' is stronger inside
a class declaration. Everything else predicts zero.
"""
READS = ()

EXTENSION = {
    'extend': 5.35, 'extends': 5.7, 'extended': 4.75,
    'extending': 5.2, 'extension': 5.05, 'extensions': 4.3,
}
TRANSLATIONS = {
    '延': 7.4, '延续': 6.0, '延續': 6.0, '延伸': 6.0,
    '延长': 4.5, '延長': 4.5, '扩展': 3.7, '擴展': 3.7,
    '延期': 3.5, '拓展': 3.0, '伸': 3.0, '擴': 2.7,
    '延迟': 2.5, '延遲': 2.5, '扩大': 1.9, '擴大': 1.9,
    '蔓延': 1.9, '연': 1.5, '확': 1.35, 'продолж': 1.3,
    '继续': 1.3, '繼續': 1.3, '展': 1.2, '发展': 0.85,
    '發展': 0.85, '連': 0.75, '连': 0.75, '一直': 0.75,
    '限制': 0.8, '好久': 0.7, '修正': 0.5,
}


def word(token):
    return token.strip().lower().lstrip('._-/')


def strength(token):
    w = word(token)
    if w in EXTENSION:
        value = EXTENSION[w]
        if token.startswith('.'):
            return 2.1 if w.startswith('extend') else 3.2
        return value
    if w == 'ext':
        return 1.6
    if w.startswith(('extens', 'extent')):
        return 0.7 if w.endswith('ly') else 1.1
    if w in {'continue', 'continues', 'continued', 'continuing', 'continuation'}:
        return 1.0
    if w.startswith(('expand', 'expansion', 'stretch', 'elong')) or w == 'beyond':
        return 1.2
    if w.startswith(('delay', 'postpon', 'prolong')):
        return 1.5
    if w.startswith(('restrict', 'relax', 'repeat', 'flexib', 'twist')):
        return 0.8
    if w.startswith('modif'):
        return 0.8 if w == 'modify' else 0.4
    if w in {'generalized', 'generalize'}:
        return 1.1
    if w in {'longer', 'lengthy', 'advanced', 'scaling'}:
        return 0.5
    return TRANSLATIONS.get(token.strip(), 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    old = '' if reset else carry[1]
    in_class = False if reset else carry[2]
    token = prefix.token_strings[-1]
    w, prev = word(token), word(old)
    value = strength(token)
    if w == 'extends':
        value = 6.6 if in_class else 5.1

    # Recognize morphologically meaningful token joins.
    if prev == 'ext' and token.isalpha():
        value = strength('ext' + w)
        if w in {'end', 'ends', 'ended', 'ending'}:
            value = 5.5
        elif w == 'ender':
            value = 3.1
        elif w in {'ens', 'ensive'}:
            value = 1.5
    elif prev == 'exp' and w in {'and', 'anding', 'anded', 'ands'}:
        value = 1.8
    elif prev == 'general' and w in {'ization', 'izations', 'ized', 'izes'}:
        value = 2.0
    elif prev in {'elong', 'extrapol'} and w in {'ation', 'ated'}:
        value = 1.1 if prev == 'elong' else 1.8

    if w == 'the':
        if prev in EXTENSION and prev.startswith('extend'):
            value = 0.48 * strength(old)
        elif prev.startswith(('expand', 'continu', 'modif', 'delay')):
            value = 0.65
        elif prev == 'beyond':
            value = 0.65
    elif w == 'of':
        if prev in {'extension', 'extensions'}:
            value = 0.8 * strength(old)
        elif prev in {'expansion', 'continuation', 'restriction'}:
            value = 1.2
        elif prev.startswith('modification') or prev in {'extent', 'stretch'}:
            value = 0.8
    elif w == 'to':
        value = 0.1 * strength(old)
        if prev in {'continue', 'continues', 'continued', 'continuing'}:
            value = 0.25
    elif w in {'his', 'her', 'its', 'their', 'my', 'our', 'your', 'a'}:
        value += 0.12 * strength(old)
    if any(c in token for c in '\n{};<>') or w == 'extends':
        in_class = False
    if w == 'class':
        in_class = True
    return (doc, token, in_class), float(value)

