    elif any(part in token for part in (
        "expan", "prolong", "continu", "postpon", "stretch", "broadening",
        "broaden", "widening", "repeated", "repeat", "delay", "delayed",
        "duration", "lengthy", "longer", "modif", "restrict", "advanced",
    )):
        value = 0.9
    elif any(part in token for part in (
        "eyond", "progress", "growth", "relaxation", "relaxed", "beyond",
        "extensibility", "extendable", "flexible", "limitation",
    )):
        value = 0.55
    elif any(part in token for part in (
        "延", "伸", "縮", "扩", "擴", "续", "續", "继续", "繼續",
        "限制", "修改", "发展", "发展", "продолж", "распростран",
        "länger", "prolongée", "extensões",
    )):
        value = 0.9
    else:
