    elif s == '.githubusercontent':
        value = 0.78 if previous == 'user-images' else 0.12
    elif s == '.h':
        value = 0.67 if previous in C_IO_HEADERS else 0.23
        if previous in C_HEADERS:
            value = 0.46
    elif s == 'github' or s == '.apache':
