CHROME = {
    "Posts": 0.6, " Posts": 0.6, "posts": 0.3, " posts": 0.3,
    " Replies": 0.25, " replies": 0.15, " Posted": 0.16, " Thread": 0.1, " Comments": 0.08,
    " reply": 0.3, " Reply": 0.3, " Tags": 0.07, " Search": 0.07, " Email": 0.08,
    " post": 0.08, " article": 0.13, " above": 0.09, " via": 0.1, " »": 0.16,
}
# Field labels that, followed by a colon, fire on the colon.
