    previous_doc, tail = carry if carry is not None else (doc, "")
    if previous_doc != doc:
        tail = ""

    token = prefix.token_strings[-1]
    joins = bool(token) and token[0].isalnum()
    joined = (tail if joins else "") + token
    words = []
    part = ""
    for char in joined.lower():
        if char.isalnum():
            part += char
        elif part:
            words.append(part)
            part = ""
    if part:
        words.append(part)

    value = 0.0
    if any(word.startswith(CORE) for word in words):
        value = -4.8
    elif any(word.startswith(RELATED) for word in words):
        value = -0.8
    elif any(word.startswith("symmetr") for word in words):
        value = -0.8
    elif any(word.startswith("symp") for word in words):
        value = -0.6
    elif any(word.startswith("sym") for word in words):
        value = -1.3
    elif any(word.startswith(("象征", "符号", "符號")) for word in words):
        value = -1.6
    elif any(term in token for term in ("象征", "符号", "符號", "бук")):
        value = -1.6
    elif "图案" in token or "圖案" in token:
        value = -0.8
    elif "号" in token or "號" in token:
        value = -0.6

    new_tail = part[-32:]
    return (doc, new_tail), float(value)

programs.sol:
"""Eight-related forms, plus negative marker and verb-boundary responses.

Digit 8 is stronger after Latin letters and weaker after digits or a dot.
Written forms of eight, eighteen/eighty, and the eighth month also respond.
Negative rules cover ampersands (especially Rust's '&self') and continuations
of get/set. These rules omit assorted word-specific residual responses.
Only the previous token is retained; document boundaries reset that state.
"""
import re

READS = ()
EIGHT_RELATED = {
    "eight": 0.90,
    "eighth": 0.90,
    "-eight": 0.90,
    "-eighth": 0.90,
    "eighteen": 0.57,
    "eighty": 0.73,
    "viii": 0.75,
    "八": 1.45,
    "第八": 1.45,
    "august": 0.72,
    "aug": 0.49,
    "agosto": 0.49,
    "août": 0.49,
}
ACCESS_VERB = re.compile(
    r"(?:^|[^a-z])(?:get|set|got|gets|sets|getting|setting)$", re.IGNORECASE
)
FUNCTION_WORDS = {"a", "an", "the", "to", "it"}
SPATIAL_PARTICLES = {"in", "off", "over", "inside", "back"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = EIGHT_RELATED.get(word, 0.0)
    if token in {"8", "８"}:
        value = 0.95
        if previous and previous[-1].isdigit():
            value = 0.89
        elif previous.endswith("."):
            value = 0.78
        elif previous and previous[-1].isascii() and previous[-1].isalpha():
            value = 1.18

    if previous.endswith("&#") and token.isdigit():
        value -= 1.13
    elif previous.endswith("&"):
        if previous.endswith("&&"):
            value -= 0.10 if token[:1].isspace() else 0.50
        elif token == "self":
            value -= 2.70
        elif token and token[0].isalnum():
            value -= 1.40
        elif token.strip().isalpha():
            value -= 0.36
        else:
            value -= 0.78
    elif ACCESS_VERB.search(previous) and token:
        if not token[0].isspace() and (token[0].isalpha() or token[0] in "_-"):
            value -= 0.55
        elif word in {"out", "away"}:
            value -= 0.95
        elif word in SPATIAL_PARTICLES:
            value -= 0.50
        elif word == "up":
            value -= 0.12 if "set" in previous.lower() else 0.48
        elif word in FUNCTION_WORDS:
            value += 0.05
        elif token.strip().isalpha():
            value -= 0.15
    return (doc, token), float(value)

"""A sparse lexical capital/assets detector, with weaker investment/finance cues.

It responds to word pieces, not a sentence's meaning: a city called a capital
or a directory called assets still counts. Chinese/Japanese 資/资 is especially
strong by itself; longer words containing it are weaker. One-token memory
recognizes split capital/investment words and their immediate prepositions.
Korean 자 (ja) also has a negative response. Unmatched text predicts zero.
"""

READS = ()
GROUPS = (
    (-3.4, {'capital', 'kapital', 'assets'}),
    (-2.9, {'asset'}),
    (-2.8, {'investment'}),
    (-2.2, {'investments', 'tư'}),  # Vietnamese đầu tư: investment.
    (-2.05, {'investor', 'investors'}),
    (-1.75, {'investing', 'invested'}),
    (-1.35, {'invest', 'investir'}),
    (-1.15, {'funding', 'funds'}),
    (-0.9, {'funded', 'fundraising', 'fund', 'financing', 'equity',
            'portfolio', 'securities', 'shareholder', 'shareholders'}),
    (-0.65, {'financial', 'finance', 'wealth', 'treasury', 'kap', 'capit',
             '基金', '股东', '证券', '金融', '财富'}),
)
VALUES = {w: value for value, words in GROUPS for w in words}
INVEST_FORMS = {'invest', 'investment', 'investments', 'investing', 'invested'}


def lexical_value(token, previous=''):
    raw = token.strip().lstrip('/_.(-')
    word = raw.lower()
    previous = previous.lower()
    value = VALUES.get(word, 0.0)
    if word in {'资', '資'}:
        value = -7.6 if word == '资' else -6.6
    elif word in {'资本', '資本'}:
        value = -4.8
    elif '资产' in word or '資産' in word:
        value = -4.2 if len(word) == 2 else -3.0
    elif '投资' in word or '投資' in word:
        value = -3.85 if len(word) == 2 else -2.7
    elif word in {'资金', '資金'}:
        value = -3.5
    elif '资' in word or '資' in word:
        value = -2.0 if ('资本' in word or '資本' in word) else -1.0
    elif word.startswith(('capitaliz', 'capitalis')) or word == 'capitals':
        value = -1.2
    elif word.startswith('инвести'):  # Russian investment stem.
        value = -3.2
    elif word.startswith('капитал') or word == 'vốn':  # Capital.
        value = -2.5
    elif word in {'ital', 'itals', 'italize'}:
        value = -1.55 if previous.endswith(('cap', 'kap')) else -0.4
    elif word == 'ment' and previous == 'invest':
        value = -2.6
    elif word == 'unding' and previous == 'f':
        value = -0.95
    elif previous == 'capital' and word in {'ization', 'isation', 'ize', 'ise'}:
        value = -0.8
    elif previous in INVEST_FORMS and word in {'in', 'of'}:
        value = -0.85
    elif word == 'of' and previous in {'capital', 'asset', 'assets'}:
        value = -0.5 if previous == 'capital' else -0.2
    if word in {'fund', 'funds'} and raw[:1].isupper():
        value += 0.3
    if word == '자':
        value = -2.0 if token[:1].isspace() else -1.0
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token.strip().lstrip('/_.(-')), lexical_value(token, previous)

