    elif lower in {'guess', 'guesses', 'guessed', 'guessing'}:
        value = 0.75 if lower == 'guess' else 0.52
        if lower == 'guess' and prev_lower == 'i':
            value = 1.19
        elif lower == 'guess' and prev_lower in {'my', 'would', 'could'}:
            value = 0.95
        elif lower == 'guessing' and prev_lower in {"'m", '’m', 'am', 'i'}:
            value = 0.68
    elif lower in TOOLS:
        value = TOOLS[lower]
        if word == 'Calculator':
