    elif word == '器':
        value = -2.0 if len(prev) == 1 else -1.65
        if prev.endswith(('机', '機')):
            value = -0.70
        elif prev in {'水', '刀', '波', '震', '木'}:
            value = -2.8
        elif prev in {'模拟', '飞行', '转换', '充电', '播放', '放大'}:
