"""A partial lexical sketch of a sparse component.

It predicts positive values for English guess-words, the Chinese
sexagenary-cycle characters, and a few noon/midday cues. Guess followed by
“the” gets a smaller positive value. Calculator/heater terms and several
Chinese equipment characters get negative values. Everything else is zero;
this covers only recurring examples, not every activation.
"""
READS = ()

CYCLE_CHARACTERS = frozenset("子丑寅卯辰巳午未申酉戌亥甲乙丙丁戊己庚辛壬癸")
EQUIPMENT_CHARACTERS = frozenset("器炉板剂")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    document = prefix.document_ids[-1]
    previous_guess = bool(carry and carry[0] and carry[1] == document)

    if word == "guess":
        value = 0.9
    elif word.startswith("guess"):
        value = 0.5
    elif token.strip() in CYCLE_CHARACTERS:
        value = 0.9
    elif word in {"noon", "midday", "afternoon"} or "午" in token:
        value = 0.7
    elif word.startswith("calculator") or word.startswith("heater"):
        value = -0.7
