programs.sol:
"""Respond mainly to Cyrillic word pieces, especially consonant-rich beginnings.

Spaces, case, vowels versus consonants, and common Russian prefixes distinguish
strong word-beginning responses from weaker continuation/endings. Conjunctions
are weaker still. Document and chat boundary markers have separate responses.
Only the previous token's character class is retained, resetting per document.
"""
READS = ()

VOWELS = frozenset('аеёиоуыэюя')
PREFIXES = (
    'без', 'бес', 'вз', 'воз', 'вос', 'вы', 'до', 'за', 'из', 'ис',
    'на', 'над', 'недо', 'об', 'обез', 'обес', 'от', 'пере', 'по',
    'под', 'пред', 'пре', 'при', 'про', 'раз', 'рас', 'роз', 'рос',
    'с', 'со', 'су', 'у', 'чрез', 'через',
)
CONJUNCTIONS = frozenset(('и', 'а', 'но', 'или', 'либо', 'да'))
FUNCTION_WORDS = frozenset((
    'не', 'ни', 'же', 'ли', 'бы', 'как', 'что', 'это', 'который',
    'которая', 'которые', 'его', 'ее', 'её', 'их', 'он', 'она', 'оно',
    'они', 'мы', 'вы', 'я', 'ты', 'все', 'всё', 'кто', 'где', 'когда',
))
MARKERS = {
    '<|endoftext|>': 1.68, '<|im_start|>': 0.25, '<|im_end|>': -0.14,
    '<tool_call>': 0.18, '</tool_call>': -0.41,
    '<tool_response>': -0.09, '</tool_response>': -0.76,
    '<think>': 0.23, '</think>': 0.08,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    if reset:
        previous_word, previous_cyrillic = False, False
    else:
        _, previous_word, previous_cyrillic = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    letters = [c for c in lower if 'а' <= c <= 'я' or c == 'ё']
    consonants = sum(c not in VOWELS and c not in 'ьъ' for c in letters)
    vowels = sum(c in VOWELS for c in letters)
    upper = word[:1].isupper()
    spaced = text[:1].isspace()
    first_vowel = lower[:1] in VOWELS
    last_vowel = lower[-1:] in VOWELS
    has_prefix = lower.startswith(PREFIXES)

    if text in MARKERS:
        value = MARKERS[text]
    elif not letters:
        value = -0.16 if previous_cyrillic else 0.0
    elif not upper and lower in CONJUNCTIONS:
        value = (-0.23 if spaced else 0.0) if lower == 'и' else 0.2
    elif consonants == 0:
        if upper:
            value = 0.62
        elif spaced and len(letters) == 1:
            value = 1.25
        else:
            value = 0.26 if len(letters) == 1 else 0.7
    elif spaced:
        if len(letters) == 1:
            value = 0.87
        elif last_vowel:
            value = 1.66 if has_prefix else 1.34
            if lower in FUNCTION_WORDS and not has_prefix:
                value = 1.12
        elif vowels == 0:
            value = 2.44
        elif has_prefix:
            value = 2.49 if vowels / len(letters) <= 0.4 else 1.94
        else:
            value = 1.78
    elif consonants >= 2:
        value = 0.90 if last_vowel else (1.42 if has_prefix else 1.07)
    elif first_vowel:
        value = 0.52 if last_vowel else 0.87
    else:
        value = 0.68 if upper else (0.40 if len(letters) <= 2 else 0.80)

    if letters:
        if not previous_word and not reset:
            value += 0.26 if spaced else 0.76
        elif upper and not spaced and previous_word:
            value -= 0.26
    carry = (doc, text[-1:].isalpha(), bool(letters))
    return carry, float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3317 -- a "Russian word-start" detector.

What it does: this component writes a strong signal into the residual stream whenever the
current token is a Cyrillic (Russian-style) piece of text.
  * Largest on a Cyrillic piece that begins a word with a leading space and is a
    multi-letter stem or prefix (" пр", " созд", " выб", " под", " об"): about +2.
  * Medium on a single-letter Cyrillic piece with a leading space: about +1.
  * Weaker on Cyrillic word-internal pieces (no leading space): about +0.9 for multi-letter,
    +0.4 for single letters.
  * Weak on common complete short Russian words (и, а, или, для, на, не, что, как): about +0.3.
  * <|endoftext|> gives a steady +1.7, and the closing tags </tool_response> and </tool_call>
    give about -0.6.
  * Everything else (Latin text, digits, punctuation, code, CJK) gives 0.

It uses only the current token's text, so no context is needed. The numbers are the average
activation of each group on training text.
"""
import unicodedata

READS = ()

# Short, very common Russian words that are complete on their own (conjunctions, particles).
SHORT_WORDS = {"и", "а", "или", "для", "на", "не", "что", "как"}
END_OF_TEXT = "<|endoftext|>"
CLOSING_TAGS = {"</tool_response>", "</tool_call>"}


def is_cyrillic(text):
    """True if any character of the token is a Cyrillic letter."""
    return any("CYRILLIC" in unicodedata.name(ch, "") for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    if token == END_OF_TEXT:
        value = 1.7
    elif token in CLOSING_TAGS:
        value = -0.6
    elif not is_cyrillic(token):
        value = 0.0
    elif token.startswith(" "):
        if word in SHORT_WORDS:
            value = 0.3
        elif len(word) == 1:
            value = 1.0
        else:
            value = 2.0
    else:
        value = 0.4 if len(word) == 1 else 0.9
    return None, value

