CLASSES = (
    # Vehicle types.
    (2.7, 'truck trucks automobile automobiles bicycle bicycles motorcycle '
           'motorcycles scooter'),
    (2.0, 'bike bikes boat boats wheelchair caravan'),
    (1.5, 'bus buses taxi tram shuttle carriage subway freight wagon ambulance'),
    # People and actions associated with driving.
    (1.8, 'driver drivers motorist motorists cyclist cyclists'),
    (1.2, 'drive drives drove wheel wheels brake brakes braking transportation '
           'commuter commuters commuting cycling'),
    # Other forms of transport, and words for roads.
    (0.95, 'mobile auto autom horse horses cavalry aircraft airplane airplanes '
            'ship ships fleet transport railway railroad highway police'),
    (0.75, 'ride riding cart traffic road roads street streets avenue lane lanes '
            'tracks rail tunnel travel traveling travelling walking racing'),
    # Weaker associations: parts, walking, and seating.
    (0.5, 'seat seats roof speed speeds walk walked trail bridge driven knee '
           'phone smartphone iphone dog dogs cow cows'),
)
