MAKERS = set('bmw toyota nissan volkswagen renault hyundai chevrolet '
             'chrysler cadillac volvo lexus peugeot'.split())


def lexical(token):
    word = token.strip()
    if word == '车':
        return 9.2
    if word == '車':
        return 6.7
    if word in {'车辆', '车上', '车内', '车子', '新车', '单车', '行车'}:
        return 6.3
    if word in {'辆', '輛', '万辆', '一辆'}:
        return 4.3
    if word in {'车间', '火车站'}:
        return 0.8
    if word in {'车站', '停车场', '车库', '停车位', '车祸', '车牌'}:
        return 2.7
    if '车' in word or '車' in word:
        return 4.3 if len(word) == 2 else 3.7
    if word in {'驾驶', '司机', '交通', '行驶', '骑', '船', '艇', '地铁',
                '自动驾驶', '驾驶员', '公交', 'に乗', '乗り', 'バイク'}:
        return 2.2
    if word in {'乘', '驾', '驶', '舟', '牛', '犬', '飞机', '走', '走了'}:
        return 1.3
    if word in {'路', '行', '街', '轮', '馬', '马', '速', '铁路', '手机', '鞋'}:
        return 0.7
    if word == '차':
        return 3.6
    if word == 'รถ':
        return 5.2

    spaced = token[:1].isspace()
    raw = word.strip('._/-(<')
    lower = raw.lower()
    if lower in {'vehicle', 'vehicles', 'ehicle', 'ehicles'}:
        value = 5.7 if lower == 'vehicle' else 5.2
        if raw[:1].isupper():
            value -= 0.5
        return value * (1.0 if spaced else 0.78)
    if lower in {'car', 'cars'}:
        if raw.isupper():
            return 1.1
        if not spaced:
            return 2.3 if word != raw else (2.0 if raw[0].isupper() else 1.45)
        return 2.75 if raw == 'Car' else 3.4
    if lower in {'train', 'trains'}:
        if not spaced:
            return 2.25 if raw[0].isupper() else 1.45
        return 3.0 if lower == 'trains' else 2.4
    if lower == 'automotive':
        return 3.1
    if lower in {'driving', 'parking', 'parked'}:
        return 2.2
    if lower == 'jeep':
        return 3.6
    if lower in MAKERS:
        return 2.3
    if lower in {'ford', 'honda', 'ferrari', 'mustang', 'nascar', 'mercedes'}:
        return 1.4 if raw[:1].isupper() else 0.3
    if lower.startswith('автомоб') or lower in {'voiture', 'véhicule', 'vehículo'}:
        return 2.8
    if lower in {'driver', 'drivers', 'bus'} and not spaced and raw == word:
        return 1.55 if raw[0].isupper() else 0.6
    return WORDS.get(lower, 0.0) * (1.0 if spaced else 0.9)


ARTICLES = {'a', 'an', 'the', 'this', 'that', 'these', 'those'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their', 'its'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, previous_value = ('', 0.0)
    if carry is not None and carry[0] == doc:
        _, previous, previous_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    base = lexical(token)
    if '\ufffd' in token:
        # Decoding the whole prefix may finish a split vehicle character.
        last_character = prefix.text_prefixes[-1][-1:]
        if last_character and last_character in '车車辆輛':
            base = lexical(last_character)
    value = base
    if token[:1].isspace():
        if word == 'car':
            value += 0.75 if previous in POSSESSIVES else (
                0.4 if previous in ARTICLES else -0.25)
        elif word == 'train':
            value += 0.4 if previous in ARTICLES else -0.15
        elif word == 'driver':
            value += 0.2 if previous in ARTICLES else -0.1
        elif word == 'vehicle' and previous in POSSESSIVES:
            value += 0.5
        elif word == 'of':
            value += 0.18 * previous_value
    return (doc, word, base), float(value)

