            return -4.89 if spaced else -4.73
        if not spaced:
            return -4.49 if raw.startswith('-') else -3.2
    elif lower == 'lower':
        if raw.startswith('.'):
            return -2.94
        return value if spaced else -1.94
    elif lower == 'lowest':
        return value if spaced else -3.57
    if word.istitle():
        value *= 0.91
    if not spaced:
        value *= 0.83
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._-').lower()
    old_word, old_value = '', 0.0
    if carry is not None and carry[0] == doc:
        _, old_word, old_value = carry
    base = lexical_value(token)
    value = base
    if old_word == 'low' and token == 'est':
        value = 0.86 * old_value
    elif old_word in {'low', 'lower'} and token in {'ing', 'ed'}:
        value = (0.3 if old_word == 'low' else 1.0) * old_value
    elif old_word in {'low', 'high'} and token == 'ly':
        value = 0.42 if old_word == 'high' else 0.23 * old_value
    elif old_word == 'сни' and token == 'ж':
        value = 1.1 * old_value
    elif old_value < -0.8:
        if token == ' than':
            value += 0.35 * old_value
        elif token == ' of':
            value += 0.38 * old_value
        elif token == ' in':
            value += 0.17 * old_value
        elif word in SCALE_NOUNS:
            if old_word != 'high':
                value += 0.22 * old_value
            elif word in {'level', 'levels'}:
                value += 0.40
        elif token == ' the':
            value += 0.10 * old_value
        elif old_word in {'low', 'lower'} and token[:1].islower():
            value += 0.15 * old_value
    return (doc, word, base), float(value)

"""Approximate a signed continuation-of-one feature.

After 1, digits 1--4 are negative, 6--9 positive, and 0 and 5 near zero.
Number position, separators and numeral typography change the strength.
Chinese and fullwidth numerals count too.  Separate calibrations cover
1st, punctuation, single-letter labels and document-initial 1.
Only two preceding tokens are remembered; documents reset that memory.
Diffuse low-amplitude variation outside these patterns is not modelled.
"""
import unicodedata

READS = ()
# Fitted response sizes, indexed by the familiar digit value.
DIGIT_RESPONSE = (0.04, -1.23, -1.95, -1.71, -1.11,
                  -0.02, 1.02, 1.66, 2.78, 4.50)
DECIMAL_RESPONSE = (-0.03, -0.44, -0.65, -0.60, -0.41,
                    -0.04, 0.28, 0.42, 0.63, 1.09)
CHINESE_DIGITS = '零一二三四五六七八九'
SUFFIX_RESPONSE = {'st': 1.92, '.': 0.22, ')': 0.34}


def numeral(token, last=False):
    if not token:
        return None, 'none'
    c = token[-1] if last else token[0]
    if c in CHINESE_DIGITS:
        return CHINESE_DIGITS.index(c), 'Chinese'
    if len(token) != 1:
        return None, 'none'
    digit = unicodedata.digit(c, None)
    if digit is None:
        return None, 'none'
    kind = ('subscript' if 'SUBSCRIPT' in unicodedata.name(c, '') else
            'superscript' if 'SUPERSCRIPT' in unicodedata.name(c, '') else
            'ordinary')
    return int(digit), kind


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, before = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    digit, kind = numeral(token)
    prev_digit, prev_kind = numeral(previous, last=True)
    before_digit, _ = numeral(before, last=True)
    value = 0.0
    if digit is not None:
        if prev_digit == 1:
            value = DIGIT_RESPONSE[digit]
            if before_digit is not None:
                if before_digit == 1:
                    value *= 1.16 if digit < 5 else 1.02
                else:
                    value *= 1.0 if digit < 5 else 0.85
            if 'Chinese' in (kind, prev_kind):
                value *= 0.84
            if 'subscript' in (kind, prev_kind):
                value *= 0.50
            elif 'superscript' in (kind, prev_kind):
                value *= 0.28
        elif before_digit == 1:
            if previous == '.':
                value = DECIMAL_RESPONSE[digit]
            elif previous == ',':
                value = 0.15 * DIGIT_RESPONSE[digit]
            elif previous.isspace():
                value = (0.10 if '\n' in previous else 0.22) * DIGIT_RESPONSE[digit]
            elif previous in {'-', '/', ':'}:
                value = 0.08 * DIGIT_RESPONSE[digit]
        elif start and token == '1':
            value = -0.83
    elif previous == '1':
        if token in SUFFIX_RESPONSE:
            value = SUFFIX_RESPONSE[token]
        elif token.isspace() and '\t' not in token:
            value = 0.13
        elif len(token) == 1 and token.isascii() and token.isalpha():
            value = -0.53
    return (doc, token, previous), float(value)

"""Token-level load/burden and benevolence signals, not a meaning classifier.

'Load' is strongly positive; loading, transfer and saving words are weaker.
Virtue words are negative, especially 仁 (also in names and almond words).
Attached prefixes distinguish overload/unload from plain load. JSON loading
is particularly strong. A few following prepositions and word endings retain
some of the load signal. State resets at each document; other tokens give zero.
"""
import re

READS = ()

# Chinese/Japanese characters and words for loads and bearing burdens.
LOAD_WORDS = {
    '载': 3.4, '載': 3.8, '加载': 4.1, '承载': 3.2,
    '负载': 6.4, '负荷': 4.9, '荷': 2.3,
    '负担': 1.7, '承担': 1.8, '担': 1.8, '負': 1.45,
    '负': 0.5, '下载': 0.85,
}
# Benevolence, righteousness, compassion, filial piety, courage and loyalty.
VIRTUE_WORDS = {
    '仁': -8.0, '义': -1.5, '義': -1.2, '善': -1.3,
    '善良': -1.2, '慈': -2.0, '慈善': -1.2, '孝': -1.7,
    '惠': -1.1, '豪': -1.6, '勇': -1.0, '忠': -0.75,
}


def lexical_value(token, word, previous, start):
    if word in {'load', 'loads'}:
        value = 6.0 + (0.6 if token.startswith('.') else 0.0)
        if start:
            value += 2.0
        # Prefixes count only when joined without a token-leading separator.
        if token[:1].isalpha():
            for ending, amplitude in (
                ('over', 1.9), ('un', 2.9), ('off', 2.8),
                ('down', 2.2), ('up', 3.0), ('re', 3.1), ('work', 4.8),
            ):
                if previous.endswith(ending):
                    return amplitude
        if word == 'load' and token.startswith('.') and previous == 'json':
            return 9.5
        if token == 'Load' and previous == 'safe':
            return 9.3
        return value
    if word in {'loaded', 'loading'}:
        if token[:1].isalpha() and previous.endswith(('un', 'down', 'up')):
            return 1.5
        return 5.1 if start else 3.2
    if word in {'loader', 'loaders'}:
        return 1.35 if token.startswith('_') else 2.1
    if word in {'eload', 'oload', 'oad'}:  # Split endings of load compounds.
        return {'eload': 4.7, 'oload': 3.2, 'oad': 1.2}[word]
    if word.startswith('load') or word in {'isloading', 'onload'}:
        return 3.0
    if word in {'reload', 'reloaded', 'reloading', 'preload', 'unload'}:
        return 2.2
    if word == 'workload':
        return 3.2
    if word in {'overload', 'overloaded'}:
        return 0.85
    if word.startswith('download'):
        return 0.5 if word != 'download' else 0.67
    if word.startswith('upload') or word == 'payload':
        return 0.8
    if word in {'save', 'saves', 'saved', 'saving', 'savings'}:
        return 0.65
    if word in {'burden', 'burdens', 'burdened'}:
        return 1.25
    if word in {'heavy', 'heavily'}:
        return 0.3
    if word in {'lb', 'lbs'}:
        return 0.45
    if word in {'pound', 'pounds'}:
        return 0.85
    if word in {'carg', 'carga', 'cargar'}:  # Spanish: load/carry.
        return 1.6
    if word in {'руз', 'груз', 'нагруз'}:  # Russian load/cargo stems.
        return {'руз': 2.1, 'груз': 1.5, 'нагруз': 4.7}[word]
    if word in {'generous', 'philanth', 'altru'}:
        return -1.2
    if word in {'charity', 'charities', 'charitable'}:
        return -0.8
    if word in {'generosity', 'kindness', 'compassion', 'righteousness'}:
        return -0.35
    if word in {'mercy', 'compassionate'}:
        return -0.6
    if word in VIRTUE_WORDS:
        if word == '仁' and previous.endswith('杏'):  # Almond kernel.
            return -7.1
        return VIRTUE_WORDS[word]
    if word in LOAD_WORDS:
        if word == '载' and previous.endswith('下'):
            return 1.55
        if word == '载' and previous.endswith('荷'):
            return 5.9
        return LOAD_WORDS[word]
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    start = carry is None or carry[0] != document
    previous, previous_load = ('', 0.0) if start else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().strip('._-/()<>').lower()
    value = lexical_value(token, word, previous, start)

    if previous_load and not value:
        # The next preposition can still express the load relationship.
        following = {
            'of': 0.39, 'on': 0.22, 'the': 0.13,
            'from': 0.08, 'into': 0.08, 'onto': 0.15, 'with': 0.15,
        }
        if word in following:
            value = previous_load * following[word]
        elif token in {'ings', 'ers'}:
            value = previous_load * (0.44 if token == 'ings' else 0.32)

    # Remember only the trailing word, so split compound prefixes are recognized.
    joined = previous + token if token[:1].isalpha() else token
    tail = re.search(r'[^\W\d_]+$', joined)
    previous = tail.group().lower()[-40:] if tail else ''
    load = value if word in {'load', 'loads', 'loaded', 'loading'} else 0.0
    return (document, previous, load), float(value)

programs.luna:
"""Approximate the component with load, transfer, and burden-related words.

It responds most strongly to “load” and its inflections. A few immediate
continuations after “load” get a smaller response; file-transfer words and
burden or weight terms get weaker responses. Other tokens get zero.
"""
READS = ()


def clean(token):
    return token.strip().lower().strip(
        " \t\r\n.,:;!?()[]{}\"'`_"
    )


def step(carry, prefix, upstream):
    word = clean(prefix.token_strings[-1])
    if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = clean(prefix.token_strings[-2])
        if previous == "load" and word in {"of", "on", "ings"}:
            return None, 1.9

    if word in {"load", "loadings"}:
        return None, 5.3
    if word in {"loaded", "loading"}:
        return None, 3.6
    if word in {"save", "saved", "download", "downloads", "upload", "uploaded"}:
        return None, 0.65
    if word in {"burden", "burdening", "負", "负"}:
        return None, 1.0
    if word in {"lb", "pound", "pounds", "heavily"}:
        return None, 0.55
    return None, 0.0

programs.sol:
"""Detect conventional expressions of social warmth and courtesy.

Gratitude, apologies and greetings give the largest responses. Positive
appraisals, agreement, respectful address and conversational hedges give
smaller ones. Capitals and word boundaries matter, as do a few familiar
phrases (thank you, grateful for, happy to). Unlisted tokens are near zero,
apart from small responses at turn endings. This is a lexical detector:
it can also fire on non-social uses of these words.
"""
READS = ()

# These are words or recognizable pieces of courtesy expressions, not ids.
WORD_GROUPS = (
    # Gratitude and apologies.
    (5.3, {'thanks'}),
    (3.8, {'thank', 'thanked', 'thanking', 'gratitude'}),
    (3.4, {'grateful', 'thankful', 'apologize', 'apologise',
           'apologies', 'sincerely'}),
    (4.3, {'sorry'}),
    # Greetings, leave-taking and courteous acknowledgements.
    (3.3, {'bonjour', 'gracias', 'danke', 'goodbye', 'greetings',
           'farewell', 'cheers'}),
    (2.2, {'alright', 'dank', 'apology', 'благодар'}),
    (2.7, {'hola', 'chào', 'congratulations', 'condolences'}),
    (2.1, {'welcome', 'regards', 'bye', 'greeting', 'kudos', 'saludos'}),
    (1.5, {'好的', 'appreciated', 'appreciation', 'appreciate', 'kindly', 'glad'}),
    (1.2, {'please', 'pleased', 'regret'}),
    # Positive appraisals, agreement and tentative discourse.
    (1.0, {'great', 'greatly', 'perhaps', 'unfortunately'}),
    (0.8, {'maybe', 'yes', 'oh', 'okay', 'sir', 'folks', 'guys', 'lovely'}),
    (0.6, {'respect', 'regard', 'honor', 'honored', 'courtesy', 'pleasure',
           'happy', 'love', 'enjoyed', 'hope', 'nice', 'excellent', 'despite',
           'alternatively', 'delighted', 'excited', 'mr', 'dr', 'ah'}),
    (0.45, {'hmm', 'wow', 'attached', 'ok', 'wish'}),
    # Chinese thanks, respect, greetings; Japanese polite forms.
    (7.5, {'谢谢'}),
    (6.8, {'谢'}),
    (5.8, {'謝', '感谢'}),
    (4.0, {'敬'}),
    (3.6, {'感謝', '尊敬', '谢谢你', '你好', '衷心', '感激', '抱歉'}),
    (3.0, {'各位', '很高兴', '亲爱', '道歉', '歉', 'こんにちは', '嗨', 'お願い',
           'ありがとうございます', 'ありがとうございました'}),
    (2.0, {'欢迎', '歡迎', '欢迎您', '迎', '客气'}),
    (1.7, {'祝', '申し', 'ございます', 'おります', '致します', 'いたします'}),
    (1.3, {'いただ'}),
    (0.4, {'です', 'ます'}),
    (0.6, {'好'}),
    (1.0, {'礼', '禮', 'ご', 'お', '大家', '致', '恕', '恩'}),
    (0.7, {'请', '請', '希望', 'ください', '亲', '您的'}),
)
RESPONSE = {word: value for value, words in WORD_GROUPS for word in words}
# Responses on the last piece when a tokenizer splits a courtesy word.
SPLIT_WORDS = {'sincerely': 4.2, 'apologies': 4.2, 'gracias': 3.2,
               'greeting': 3.4, 'kudos': 2.2, 'saludos': 3.0,
               'welcome': 2.1, 'congrats': 3.2, 'tolong': 0.6}


def clean_word(token):
    text = token.strip()
    if text.startswith(('<|', '</')):
        return text
    return text.strip("()[]{}<>\"'.,!?;:")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_doc = carry is None or carry[0] != doc
    previous_raw = '' if new_doc else carry[1]
    previous = clean_word(previous_raw).lower()
    before_previous = '' if new_doc else clean_word(carry[2]).lower()
    token = prefix.token_strings[-1]
    raw = clean_word(token)
    word = raw.lower()
    capitalized = raw[:1].isupper() and not raw.isupper()
    leading_space = token[:1].isspace()
    value = RESPONSE.get(word, 0.0)
    if word in {'ah', 'oh', 'yes', 'wow', 'hmm', 'okay', 'ok'}:
        if not leading_space and not raw[:1].isupper():
            value *= 0.25
    if word == 'for':
        value = 0.09
    elif word in {'very', 'really'}:
        value = 0.27

    if word == 'thank':
        value += 0.45 * capitalized + 0.35 * (capitalized and not leading_space)
        if new_doc:
            value += 2.0
    elif word == 'thanks':
        value += 0.6 * (capitalized and not leading_space)
        if previous in {'many', 'special'}:
            value = 7.7
    elif word in {'hi', 'hello'}:
        if capitalized:
            value = 4.5 if word == 'hi' else 4.8
            if leading_space:
                value -= 1.2 if word == 'hi' else 0.5
        else:
            value = 1.7 if word == 'hi' else 3.0
            if leading_space:
                value += 0.8 if word == 'hi' else 1.1
        if new_doc:
            value += 2.7
    elif word == 'hey':
        value = (2.2 if leading_space else 2.8) if capitalized else 1.3
        if new_doc:
            value += 2.0
    elif word == 'sorry' and not leading_space and not capitalized:
        value = 3.3
    elif word == 'regards':
        value = 5.5 if capitalized and leading_space else 4.4 if capitalized else 2.2
        if previous in {'best', 'kind', 'warm'}:
            value = 4.6
    elif word == 'dear':
        value = 3.7 if capitalized else 1.5
    elif word == 'good':
        value = 1.0 if capitalized else 0.45
        if previous == 'a':
            value -= 0.2
        elif previous in {'very', 'really'}:
            value += 0.5
    elif word in {'great', 'nice', 'yes', 'okay', 'hope'} and capitalized:
        value += 0.25

    # The token can be the second half of a courteous expression.
    if word == 'you' and previous in {'thank', 'thanking'}:
        value = 5.8 if clean_word(previous_raw)[:1].isupper() else 4.5
    elif word in {'for', 'to'}:
        if previous in {'grateful', 'thankful'}:
            value = 3.0
        elif previous in {'thanks', 'gratitude', 'sorry', 'apologies'}:
            value = 1.5
        elif previous == 'you' and before_previous == 'thank':
            value = 2.0
        elif word == 'to' and previous in {'happy', 'pleased'}:
            value = 1.9
        elif word == 'to' and previous in {'glad', 'welcome', 'delighted', 'excited'}:
            value = 1.2
    elif word == 'very' and previous == 'you' and before_previous == 'thank':
        value = 0.65
    elif word == 'much' and previous == 'very':
        value = 1.6 if before_previous == 'you' else 0.7
    elif not leading_space and previous + word in SPLIT_WORDS:
        value = SPLIT_WORDS[previous + word]
    elif word == '-you' and previous == 'thank':
        value = 3.4
    elif token.startswith((',', '!')) and previous in {'hello', 'hi', 'hey'}:
        value = 1.0
    elif word == '</think>':
        value = 0.72
    elif word == '<|im_end|>':
        value = -0.1 if previous == '</tool_call>' else 0.3
        if previous_raw.endswith(('.', '?', '!', '。', '？')):
            value = 0.56

    return (doc, token.strip(), previous_raw), float(value)

programs.luna:
"""Approximate a word-level social appraisal and reaction signal."""
READS = ()

REACTIONS = {
    "ah", "aha", "oh", "wow", "hmm", "yes", "yeah", "yep",
    "perhaps", "maybe", "indeed", "sure", "sorry",
}
COURTESY = {
    "please", "thank", "thanks", "welcome", "courtesy", "respect",
    "honored", "honour", "pleasure", "grateful", "appreciate", "mr",
    "mrs", "sir", "madam", "graz", "gerne", "礼", "请", "นะ",
}
APPRAISAL = {
    "great", "good", "glad", "happy", "nice", "fine", "excellent",
    "wonderful", "beautiful", "lovely", "love", "awesome", "delighted",
    "rad", "très", "当然", "buenos",
}
ROOTS = ("thank", "respect", "honor", "pleasur", "courtes", "grate", "appreciat")
TERMS = REACTIONS | COURTESY | APPRAISAL


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.lstrip("'\"([{“‘").rstrip(".,!?;:。？！、")
    document = prefix.document_ids[-1]
    previous_was_thank = (
        carry is not None and carry[0] and carry[1] == document
    )
    active = word in TERMS
    active |= word.startswith(ROOTS)
    if word == "you" and previous_was_thank:
        active = True
    return (word in ("thank", "thanks"), document), 0.58 if active else 0.0
